package rs117.hd.utils;

import java.text.DecimalFormat;
import java.util.Arrays;

import static rs117.hd.utils.MathUtils.*;

public class Matrix {
	private static final float EPS = 1e-6f;

	/**
	 * Utility class for working with column-major m x n matrices.
	 */

	public static float[] copy(float[] m) {
		return Arrays.copyOf(m, m.length);
	}

	public static void solve(float[] m, int rows, int columns) {
		int square = min(columns, rows);
		columns:
		for (int j = 0; j < square; j++) {
			for (int i = j; i < rows; i++) {
				var f = m[j * rows + i];
				if (abs(f) < EPS)
					continue;

				// Swap the row into the right position
				if (i != j) {
					for (int k = 0; k < rows * columns; k += rows) {
						var tmp = m[k + j];
						m[k + j] = m[k + i];
						m[k + i] = tmp;
					}
				}

				// Divide by the first entry of the row
				if (abs(f - 1) > EPS) {
					f = 1 / f;
					for (int k = 0; k < rows * columns; k += rows)
						m[k + j] *= f;
				}

				// Reduce other rows
				for (int r = 0; r < rows; r++) {
					if (r == j)
						continue;
					var g = m[j * rows + r];
					if (abs(g) > EPS)
						for (int k = 0; k < rows * columns; k += rows)
							m[k + r] -= g * m[k + j];
				}

				continue columns;
			}

			throw new IllegalArgumentException("Linear system does not have a solution:\n" + Matrix.format(m, rows, columns));
		}
	}

	public static String format(float[] m, int rows, int columns) {
		String[] f = new String[m.length];
		var format = new DecimalFormat("0.##");
		int maxdigits = 0;
		int maxfractions = 0;
		for (int i = 0; i < rows * columns; i++) {
			float v = m[i];
			if (abs(v) < .01)
				v = 0;
			f[i] = format.format(v);
			var j = f[i].indexOf('.');
			if (j == -1) {
				maxdigits = max(maxdigits, f[i].length());
			} else {
				maxdigits = max(maxdigits, j);
				maxfractions = max(maxfractions, f[i].length() - j);
			}
		}

		StringBuilder str = new StringBuilder();

		for (int row = 0; row < rows; row++) {
			for (int col = 0; col < columns; col++) {
				int idx = col * rows + row;
				int dot = f[idx].indexOf('.');
				if (dot == -1) {
					int padLeft = maxdigits - f[idx].length();
					if (padLeft > 0)
						f[idx] = " ".repeat(padLeft) + f[idx];
					f[idx] += " ".repeat(maxfractions);
				} else {
					int padLeft = maxdigits - dot;
					if (padLeft > 0)
						f[idx] = " ".repeat(padLeft) + f[idx];
					int padRight = maxfractions - (f[idx].length() - dot);
					if (padRight > 0)
						f[idx] += " ".repeat(padRight);
				}

				if (col == 0)
					str.append("[ ");
				str.append(f[idx]).append(" ");
				if (col == columns - 1) {
					str.append("]");
					if (idx != m.length - 1)
						str.append("\n");
				}
			}
		}

		return str.toString();
	}
}

package rs117.hd.utils;

import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentLinkedQueue;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;

@Slf4j
public final class DestructibleHandler {
	private static final ConcurrentLinkedQueue<Destructible> PENDING_DESTRUCTION = new ConcurrentLinkedQueue<>();
	private static final ConcurrentLinkedQueue<Destructible> LEAKED_DESTRUCTIBLE = new ConcurrentLinkedQueue<>();
	private static final StringBuilder sb = new StringBuilder();
	private static final HashMap<Class<?>, Integer> totalLeakedCount = new HashMap<>();

	@Getter
	private static boolean isShuttingDown = false;

	public static void queueDestruction(Destructible destructible) {
		PENDING_DESTRUCTION.add(destructible);
	}

	public static void destroy(Destructible destructible) {
		PENDING_DESTRUCTION.remove(destructible);
		LEAKED_DESTRUCTIBLE.remove(destructible);

		destructible.destroy();
	}

	public static void queueLeakedDestruction(Destructible destructible) {
		LEAKED_DESTRUCTIBLE.add(destructible);
	}

	public static void flushPendingDestruction() {
		flushPendingDestruction(false);
	}

	public static void flushPendingDestruction(boolean isShutdown) {
		try {
			isShuttingDown = isShutdown;

			Destructible destructable;
			while ((destructable = PENDING_DESTRUCTION.poll()) != null)
				destructable.destroy();

			if (isShutdown) {
				// Perform GC + finalization to ensure we pick up on any leaks during shutdown
				for (int i = 0; i < 5; i++) {
					System.gc();
					System.runFinalization();
				}
			}

			if (LEAKED_DESTRUCTIBLE.isEmpty())
				return;

			sb.setLength(0);
			sb.append("Leaked Destructible detected, count: ").append(LEAKED_DESTRUCTIBLE.size()).append("\n");
			while ((destructable = LEAKED_DESTRUCTIBLE.poll()) != null) {
				sb.append(" * ").append(destructable.getClass().getSimpleName()).append(" | ").append(destructable).append("\n");
				destructable.destroy();

				// Track the amount that type has leaked over the course of the session
				int typeLeakCount = totalLeakedCount.getOrDefault(destructable.getClass(), 0);
				totalLeakedCount.put(destructable.getClass(), typeLeakCount + 1);
			}

			sb.append("Total leaked by Type:");
			for (Map.Entry<Class<?>, Integer> entry : totalLeakedCount.entrySet())
				sb.append("\n * ").append(entry.getKey()).append(": ").append(entry.getValue());

			log.warn(sb.toString());
		} finally {
			isShuttingDown = false;
		}
	}
}

package rs117.hd.utils;

import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.*;
import rs117.hd.scene.GamevalManager;

@Singleton
public class NpcDisplacementCache {
	private static final int MAX_SIZE = 100;
	private static final Set<String> ANIM_IGNORE_LIST = Set.of("HOVER", "FLY", "IMPLING", "SWAN", "DUCK", "SWIM");

	@Inject
	private GamevalManager gamevalManager;

	public static class Entry {
		public boolean canDisplace;
		public int idleRadius;
		public long lastAccessMs;

		{
			reset();
		}

		public Entry reset() {
			canDisplace = true;
			idleRadius = -1;
			lastAccessMs = 0;
			return this;
		}
	}

	private final HashMap<Integer, Entry> cache = new HashMap<>(MAX_SIZE);
	private Set<Integer> ANIM_ID_IGNORE_LIST = Collections.emptySet();

	public void initialize() {
		HashSet<Integer> idsToIgnore = new HashSet<>();
		for (var substringToIgnore : ANIM_IGNORE_LIST)
			for (var entry : gamevalManager.getAnims().entrySet())
				if (entry.getKey().contains(substringToIgnore))
					idsToIgnore.add(entry.getValue());
		ANIM_ID_IGNORE_LIST = Set.copyOf(idsToIgnore);
	}

	public void destroy() {
		ANIM_ID_IGNORE_LIST = Collections.emptySet();
		cache.clear();
	}

	public int size() {
		return cache.size();
	}

	public void clear() {
		cache.clear();
	}

	public Entry get(NPC npc) {
		int npcId = npc.getId();
		var entry = cache.get(npcId);

		if (entry == null) {
			if (cache.size() >= NpcDisplacementCache.MAX_SIZE) {
				long oldestMs = Long.MAX_VALUE;
				int oldestNpcId = -1;
				for (var e : cache.entrySet())
					if (e.getValue().lastAccessMs < oldestMs)
						oldestNpcId = e.getKey();
				entry = cache.remove(oldestNpcId).reset();
			} else {
				entry = new NpcDisplacementCache.Entry();
			}
			cache.put(npcId, entry);

			// Check if NPC is allowed to displace
			int animId = npc.getWalkAnimation();
			entry.canDisplace = animId == -1 || !ANIM_ID_IGNORE_LIST.contains(animId);
		}

		entry.lastAccessMs = System.currentTimeMillis();
		return entry;
	}
}

