package rs117.hd.renderer.zone;

import java.util.Arrays;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import rs117.hd.utils.collections.ConcurrentPool;
import rs117.hd.utils.collections.PrimitiveIntArray;

import static rs117.hd.renderer.zone.Zone.VERT_SIZE;
import static rs117.hd.utils.MathUtils.*;

@Slf4j
public final class FacePrioritySorter implements AutoCloseable {
	public static ConcurrentPool<FacePrioritySorter> POOL;

	public static final int MAX_FACE_COUNT = 8192;
	private static final int MAX_DIAMETER = 6000;
	private static final int MAX_FACES_PER_PRIORITY = 4000;
	private static final int PRIORITY_COUNT = 12;

	public final int[] faceDistances = new int[MAX_FACE_COUNT];

	private final int[] orderedFaces = new int[PRIORITY_COUNT * MAX_FACES_PER_PRIORITY];
	private final int[] numOfPriority = new int[PRIORITY_COUNT];
	private final int[] eq10 = new int[MAX_FACES_PER_PRIORITY];
	private final int[] eq11 = new int[MAX_FACES_PER_PRIORITY];
	private final int[] lt10 = new int[PRIORITY_COUNT];

	private final int[] zsortHead = new int[MAX_DIAMETER];
	private final int[] zsortTail = new int[MAX_DIAMETER];
	private final int[] zsortNext = new int[MAX_FACE_COUNT];

	void sortModelFaces(PrimitiveIntArray visibleFaces, Model model, boolean depthOnly) {
		final int diameter = model.getDiameter();
		if (diameter <= 0 || diameter >= MAX_DIAMETER)
			return;

		int unsortedCount = 0;
		int minFz = diameter, maxFz = 0;
		boolean needsClear = true;

		// Build the z-sorted linked list of faces
		for (int i = 0; i < visibleFaces.length; ++i) {
			final int faceIdx = visibleFaces.array[i];
			if (faceDistances[faceIdx] == Integer.MIN_VALUE) {
				orderedFaces[unsortedCount++] = faceIdx;
				continue;
			}

			if (needsClear) {
				Arrays.fill(zsortHead, 0, diameter + 1, -1);
				Arrays.fill(zsortTail, 0, diameter + 1, -1);
				needsClear = false;
			}

			final int distance = clamp(faceDistances[faceIdx], 0, diameter);
			final int tailFaceIdx = zsortTail[distance];
			if (tailFaceIdx == -1) {
				zsortHead[distance] = zsortTail[distance] = faceIdx;
				zsortNext[faceIdx] = -1;

				minFz = min(minFz, distance);
				maxFz = max(maxFz, distance);
			} else {
				zsortNext[tailFaceIdx] = faceIdx;
				zsortNext[faceIdx] = -1;
				zsortTail[distance] = faceIdx;
			}
		}

		if (visibleFaces.length - unsortedCount == 0)
			return; // No faces to sort, so don't modify the visible faces array

		visibleFaces.reset();
		if (unsortedCount > 0) // Push unsorted faces to be drawn first
			visibleFaces.put(orderedFaces, 0, unsortedCount);

		final byte[] priorities = depthOnly ? null : model.getFaceRenderPriorities();
		if (priorities == null) {
			for (int i = maxFz; i >= minFz; --i) {
				for (int f = zsortHead[i]; f != -1; f = zsortNext[f])
					visibleFaces.put(f);
			}
			return;
		}

		Arrays.fill(numOfPriority, 0);
		Arrays.fill(lt10, 0);

		for (int i = maxFz; i >= minFz; --i) {
			for (int f = zsortHead[i]; f != -1; f = zsortNext[f]) {
				final int pri = priorities[f];
				final int idx = numOfPriority[pri]++;

				orderedFaces[pri * MAX_FACES_PER_PRIORITY + idx] = f;

				if (pri < 10)
					lt10[pri] += i;
				else if (pri == 10)
					eq10[idx] = i;
				else
					eq11[idx] = i;
			}
		}

		int avg12 = (numOfPriority[1] + numOfPriority[2]) > 0 ?
			(lt10[1] + lt10[2]) / (numOfPriority[1] + numOfPriority[2]) : 0;

		int avg34 = (numOfPriority[3] + numOfPriority[4]) > 0 ?
			(lt10[3] + lt10[4]) / (numOfPriority[3] + numOfPriority[4]) : 0;

		int avg68 = (numOfPriority[6] + numOfPriority[8]) > 0 ?
			(lt10[6] + lt10[8]) / (numOfPriority[6] + numOfPriority[8]) : 0;

		int drawnFaces = 0;
		int numDynFaces = numOfPriority[10];
		int dynBase = 10 * MAX_FACES_PER_PRIORITY;
		int[] dynDist = eq10;

		if (numDynFaces == 0) {
			numDynFaces = numOfPriority[11];
			dynBase = 11 * MAX_FACES_PER_PRIORITY;
			dynDist = eq11;
		}

		int currFaceDistance = drawnFaces < numDynFaces ? dynDist[drawnFaces] : -1000;

		for (int pri = 0; pri < 10; ++pri) {
			while (
				pri == 0 && currFaceDistance > avg12 ||
				pri == 3 && currFaceDistance > avg34 ||
				pri == 5 && currFaceDistance > avg68
			) {
				visibleFaces.put(orderedFaces[dynBase + drawnFaces++]);

				if (drawnFaces == numDynFaces && dynBase == 10 * MAX_FACES_PER_PRIORITY) {
					drawnFaces = 0;
					numDynFaces = numOfPriority[11];
					dynBase = 11 * MAX_FACES_PER_PRIORITY;
					dynDist = eq11;
				}

				currFaceDistance = drawnFaces < numDynFaces ? dynDist[drawnFaces] : -1000;
			}

			visibleFaces.put(
				orderedFaces,
				pri * MAX_FACES_PER_PRIORITY,
				numOfPriority[pri]
			);
		}

		while (currFaceDistance != -1000) {
			visibleFaces.put(orderedFaces[dynBase + drawnFaces++]);

			if (drawnFaces == numDynFaces && dynBase == 10 * MAX_FACES_PER_PRIORITY) {
				drawnFaces = 0;
				numDynFaces = numOfPriority[11];
				dynBase = 11 * MAX_FACES_PER_PRIORITY;
				dynDist = eq11;
			}

			currFaceDistance = drawnFaces < numDynFaces ? dynDist[drawnFaces] : -1000;
		}
	}

	void sortStaticModelFacesByDistance(
		Zone.AlphaModel m,
		int yawCos, int yawSin,
		int pitchCos, int pitchSin
	) {
		final int radius = m.radius;
		final int diameter = 1 + radius * 2;
		if (diameter >= MAX_DIAMETER)
			return;

		final int faceCount = m.packedFaces.length;

		Arrays.fill(zsortHead, 0, diameter, -1);
		Arrays.fill(zsortTail, 0, diameter, -1);

		int minFz = diameter, maxFz = 0;
		for (int i = 0; i < faceCount; ++i) {
			final int packed = m.packedFaces[i];
			final int x = packed >> 21;
			final int y = (packed << 11) >> 22;
			final int z = (packed << 21) >> 21;

			int fz = ((z * yawCos - x * yawSin) >> 16);
			fz = ((y * pitchSin + fz * pitchCos) >> 16) + radius;

			if (zsortTail[fz] == -1) {
				zsortHead[fz] = zsortTail[fz] = i;
				zsortNext[i] = -1;

				minFz = min(minFz, fz);
				maxFz = max(maxFz, fz);
			} else {
				int lastFace = zsortTail[fz];
				zsortNext[lastFace] = i;
				zsortNext[i] = -1;
				zsortTail[fz] = i;
			}
		}

		final int start = m.startpos / (VERT_SIZE >> 2);
		for (int i = maxFz; i >= minFz; --i) {
			for (int f = zsortHead[i]; f != -1; f = zsortNext[f]) {
				if (m.sortedFacesLen >= m.sortedFaces.length)
					break;

				if (f >= faceCount)
					continue;

				final int sortedOffset = m.sortedFacesLen;
				final int faceStart = f * 3 + start;
				m.sortedFaces[sortedOffset] = faceStart;
				m.sortedFaces[sortedOffset + 1] = faceStart + 1;
				m.sortedFaces[sortedOffset + 2] = faceStart + 2;
				m.sortedFacesLen += 3;
			}
		}
	}

	@Override
	public void close() {
		POOL.recycle(this);
	}
}

package rs117.hd.renderer.zone;

import java.util.concurrent.ConcurrentLinkedQueue;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import rs117.hd.utils.DestructibleHandler;
import rs117.hd.utils.buffer.GLBuffer;
import rs117.hd.utils.buffer.GLTextureBuffer;
import rs117.hd.utils.jobs.Job;

import static org.lwjgl.opengl.GL33C.*;
import static rs117.hd.utils.buffer.GLBuffer.MAP_WRITE;

@Slf4j
public final class ZoneUploadJob extends Job {
	private static final ConcurrentLinkedQueue<ZoneUploadJob> POOL = new ConcurrentLinkedQueue<>();

	private WorldViewContext viewContext;
	private ZoneSceneContext sceneContext;

	Zone zone;
	int x, z;
	long revealAfterTimestampMs;
	boolean shouldUnmap;

	@Override
	protected void onRun() throws InterruptedException {
		try (SceneUploader sceneUploader = SceneUploader.POOL.acquire()) {
			workerHandleCancel();

			sceneUploader.onBeforeProcessTile = this::onBeforeProcessTile;
			sceneUploader.setScene(sceneContext.scene);
			sceneUploader.estimateZoneSize(sceneContext, zone, x, z);

			if (zone.sizeO > 0 || zone.sizeA > 0) {
				workerHandleCancel();

				invokeClientCallback(this::mapZoneVertexBuffers);
				workerHandleCancel();

				sceneUploader.uploadZone(sceneContext, zone, x, z);
				workerHandleCancel();

				if (shouldUnmap)
					invokeClientCallback(zone::unmap);
			}
			zone.initialized = true;
		}
	}

	private void onBeforeProcessTile(Tile t, boolean isEstimate) throws InterruptedException {
		workerHandleCancel();
	}

	private void mapZoneVertexBuffers() {
		try {
			GLBuffer o = null, a = null;
			int sz = zone.sizeO * Zone.VERT_SIZE * 3;
			if (sz > 0) {
				o = new GLBuffer("Zone::VBO::Opaque", GL_ARRAY_BUFFER, GL_STATIC_DRAW);
				o.initialize(sz);
				o.map(MAP_WRITE);
			}

			sz = zone.sizeA * Zone.VERT_SIZE * 3;
			if (sz > 0) {
				a = new GLBuffer("Zone::VBO::Alpha", GL_ARRAY_BUFFER, GL_STATIC_DRAW);
				a.initialize(sz);
				a.map(MAP_WRITE);
			}

			GLTextureBuffer f = null;
			sz = zone.sizeF * Zone.TEXTURE_SIZE;
			if (sz > 0) {
				f = new GLTextureBuffer("Zone::TBO", GL_STATIC_DRAW);
				f.initialize(sz);
				f.map(MAP_WRITE);
			}

			zone.initialize(o, a, f);
			zone.setMetadata(viewContext, sceneContext, x, z);
		} catch (Throwable ex) {
			log.warn(
				"Caught exception whilst processing zone [{}, {}] worldId [{}] group priority [{}] cancelling...\n",
				x,
				z,
				viewContext.worldViewId,
				isHighPriority(),
				ex
			);
			cancel();
		}
	}

	@Override
	protected void onCancel() {
		if (viewContext.zones[x][z] != zone)
			DestructibleHandler.queueDestruction(zone);

		// Avoid holding a reference to the context after the job is done
		viewContext = null;
		sceneContext = null;
	}

	@Override
	protected void onReleased() {
		viewContext = null;
		sceneContext = null;
		zone.uploadJob = null;
		zone = null;
		revealAfterTimestampMs = 0;
		assert !POOL.contains(this) : "Task is already in pool";
		POOL.add(this);
	}

	public static ZoneUploadJob build(
		WorldViewContext viewContext,
		ZoneSceneContext sceneContext,
		Zone zone,
		boolean shouldUnmap,
		int x,
		int z
	) {
		assert viewContext != null : "WorldViewContext cant be null";
		assert sceneContext != null : "ZoneSceneContext cant be null";
		assert zone != null : "Zone cant be null";
		assert !zone.initialized : "Zone is already initialized";

		ZoneUploadJob newTask = POOL.poll();
		if (newTask == null)
			newTask = new ZoneUploadJob();
		newTask.viewContext = viewContext;
		newTask.sceneContext = sceneContext;
		newTask.zone = zone;
		newTask.shouldUnmap = shouldUnmap;
		newTask.x = x;
		newTask.z = z;
		newTask.isReleased = false;

		return newTask;
	}

	@Override
	public String toString() {
		return String.format(
			"%s: worldViewId=%s, x=%d, z=%d",
			super.toString(),
			viewContext != null ? viewContext.worldViewId : "null",
			x, z
		);
	}

	@Override
	@SuppressWarnings("deprecation")
	protected void finalize() {
		log.debug("ZoneUploadJob finalized, it should have been pooled? - {}", this);
	}
}

