		onBeforeProcessTile = null;
	}

	public void estimateZoneSize(ZoneSceneContext ctx, Zone zone, int mzx, int mzz) throws InterruptedException {
		// Initialize the zone as containing only water, until a non-water tile is found
		zone.onlyWater = true;

		for (int z = 3; z >= 0; --z) {
			for (int xoff = 0; xoff < 8; ++xoff) {
				for (int zoff = 0; zoff < 8; ++zoff) {
					Tile t = tiles[z][(mzx << 3) + xoff][(mzz << 3) + zoff];
					if (t != null) {
						if (onBeforeProcessTile != null)
							onBeforeProcessTile.invoke(t, true);
						estimateZoneTileSize(ctx, zone, t);
					}
				}
			}
		}
	}

	public void uploadZone(ZoneSceneContext ctx, Zone zone, int mzx, int mzz) throws InterruptedException {
		var vb = zone.vboO != null ? new GpuIntBuffer(zone.vboO.mapped()) : null;
		var ab = zone.vboA != null ? new GpuIntBuffer(zone.vboA.mapped()) : null;
		var fb = zone.tboF != null ? new GpuIntBuffer(zone.tboF.mapped()) : null;
		assert fb != null;

		roofIds.clear();
		for (int level = 0; level <= 3; ++level) {
			for (int xoff = 0; xoff < 8; ++xoff) {
				for (int zoff = 0; zoff < 8; ++zoff) {
					int rid = roofs[level][(mzx << 3) + xoff][(mzz << 3) + zoff];
					if (rid > 0)
						roofIds.add(rid);
				}
			}
		}

		zone.rids = new int[4][roofIds.size()];
		zone.roofStart = new int[4][roofIds.size()];
		zone.roofEnd = new int[4][roofIds.size()];

		for (int z = 0; z <= 3; ++z) {
			this.level = z;

			if (z == 0) {
				uploadZoneLevel(ctx, zone, mzx, mzz, 0, false, roofIds, vb, ab, fb);
				uploadZoneLevel(ctx, zone, mzx, mzz, 0, true, roofIds, vb, ab, fb);
				uploadZoneLevel(ctx, zone, mzx, mzz, 1, true, roofIds, vb, ab, fb);
				uploadZoneLevel(ctx, zone, mzx, mzz, 2, true, roofIds, vb, ab, fb);
				uploadZoneLevel(ctx, zone, mzx, mzz, 3, true, roofIds, vb, ab, fb);
			} else {
				uploadZoneLevel(ctx, zone, mzx, mzz, z, false, roofIds, vb, ab, fb);
			}

			if (vb != null) {
				int pos = vb.position();
				zone.levelOffsets[z] = pos;
			}
		}

		// Upload water surface tiles to be drawn after everything else
		if (zone.hasWater && vb != null) {
			uploadZoneWater(ctx, zone, mzx, mzz, vb, fb);
			zone.levelOffsets[Zone.LEVEL_WATER_SURFACE] = vb.position();
		}
	}

	private void uploadZoneLevel(
		ZoneSceneContext ctx,
		Zone zone,
		int mzx,
		int mzz,
		int level,
		boolean visbelow,
		Set<Integer> roofIds,
		GpuIntBuffer vb,
		GpuIntBuffer ab,
		GpuIntBuffer fb
	) throws InterruptedException {
		int ridx = 0;

		// upload the roofs and save their positions
		for (int id : roofIds) {
			int pos = vb != null ? vb.position() : 0;

			uploadZoneLevelRoof(ctx, zone, mzx, mzz, level, id, visbelow, vb, ab, fb);

			int endpos = vb != null ? vb.position() : 0;

			if (endpos > pos) {
				zone.rids[level][ridx] = id;
				zone.roofStart[level][ridx] = pos;
				zone.roofEnd[level][ridx] = endpos;
				++ridx;
			}
		}

		// upload everything else
		uploadZoneLevelRoof(ctx, zone, mzx, mzz, level, 0, visbelow, vb, ab, fb);
	}

	private void uploadZoneLevelRoof(
		ZoneSceneContext ctx,
		Zone zone,
		int mzx,
		int mzz,
		int level,
		int roofId,
		boolean visbelow,
		GpuIntBuffer vb,
		GpuIntBuffer ab,
		GpuIntBuffer fb
	) throws InterruptedException {
		this.basex = (mzx - (ctx.sceneOffset >> 3)) << 10;
		this.basez = (mzz - (ctx.sceneOffset >> 3)) << 10;

		for (int xoff = 0; xoff < 8; ++xoff) {
			for (int zoff = 0; zoff < 8; ++zoff) {
				int msx = (mzx << 3) + xoff;
				int msz = (mzz << 3) + zoff;

				boolean isbridge = (settings[1][msx][msz] & Constants.TILE_FLAG_BRIDGE) != 0;
				int maplevel = level;
				if (isbridge) {
					++maplevel;
				}

				boolean isvisbelow = maplevel <= 3 && (settings[maplevel][msx][msz] & Constants.TILE_FLAG_VIS_BELOW) != 0;
				int rid;
				if (isvisbelow || maplevel == 0) {
					rid = 0;
				} else {
					rid = roofs[maplevel - 1][msx][msz];
				}

				if (isvisbelow != visbelow) {
					continue;
				}

				if (rid == roofId) {
					Tile t = tiles[level][msx][msz];
					if (t != null) {
						this.rid = rid;
						if (onBeforeProcessTile != null)
							onBeforeProcessTile.invoke(t, false);
						uploadZoneTile(ctx, zone, t, false, false, vb, ab, fb);
					}
				}
			}
		}
	}

	private void uploadZoneWater(
		ZoneSceneContext ctx,
		Zone zone,
		int mzx,
		int mzz,
		GpuIntBuffer vb,
		GpuIntBuffer fb
	) throws InterruptedException {
		this.basex = (mzx - (ctx.sceneOffset >> 3)) << 10;
		this.basez = (mzz - (ctx.sceneOffset >> 3)) << 10;

		for (int level = 0; level < MAX_Z; level++) {
			for (int xoff = 0; xoff < 8; ++xoff) {
				for (int zoff = 0; zoff < 8; ++zoff) {
					int msx = (mzx << 3) + xoff;
					int msz = (mzz << 3) + zoff;
					Tile t = tiles[level][msx][msz];
					if (t != null) {
						if (onBeforeProcessTile != null)
							onBeforeProcessTile.invoke(t, false);
						uploadZoneTile(ctx, zone, t, false, true, vb, null, fb);
					}
				}
			}
		}
	}

	private void estimateZoneTileSize(ZoneSceneContext ctx, Zone z, Tile t) {
		var tilePoint = t.getSceneLocation();
		ctx.sceneToWorld(tilePoint.getX(), tilePoint.getY(), t.getPlane(), worldPos);

		SceneTilePaint paint = t.getSceneTilePaint();
		if (paint != null && paint.getNeColor() != HIDDEN_HSL) {
			z.sizeO += 2;
			z.sizeF += 2;

			TileOverride override = tileOverrideManager.getOverride(ctx, t, worldPos);
			WaterType waterType = proceduralGenerator.seasonalWaterType(override, paint.getTexture());
			if (waterType != WaterType.NONE) {
				z.hasWater = true;
				// Since these are surface tiles, they should perhaps technically be in the alpha buffer,
				// but we'll render them in the correct order without needing face sorting,
				// so we might as well use the opaque buffer for simplicity
				z.sizeO += 2;
				z.sizeF += 2;
			} else {
				z.onlyWater = false;
			}
		}

		SceneTileModel model = t.getSceneTileModel();
		if (model != null) {
			int len = model.getFaceX().length;
			z.sizeO += len;
			z.sizeF += len;

			int tileExX = tilePoint.getX() + ctx.sceneOffset;
			int tileExY = tilePoint.getY() + ctx.sceneOffset;
			int tileZ = t.getRenderLevel();
			int overlayId = OVERLAY_FLAG | overlayIds[tileZ][tileExX][tileExY];
			int underlayId = underlayIds[tileZ][tileExX][tileExY];
			var overlayOverride = tileOverrideManager.getOverride(ctx, t, worldPos, overlayId);
			var underlayOverride = tileOverrideManager.getOverride(ctx, t, worldPos, underlayId);

			final int[] triangleTextures = model.getTriangleTextureId();
			boolean isFallbackWater = false;
			if (triangleTextures != null) {
				for (int textureId : triangleTextures) {
					if (textureId != -1 && proceduralGenerator.seasonalWaterType(TileOverride.NONE, textureId) != WaterType.NONE) {
						isFallbackWater = true;
						break;
					}
				}
			}
			WaterType overlayWaterType = proceduralGenerator.seasonalWaterType(overlayOverride, 0);
			WaterType underlayWaterType = proceduralGenerator.seasonalWaterType(underlayOverride, 0);
			boolean isOverlayWater = overlayWaterType != WaterType.NONE;
			boolean isUnderlayWater = underlayWaterType != WaterType.NONE;
			if (isFallbackWater || isOverlayWater || isUnderlayWater) {
				z.hasWater = true;
				z.sizeO += len;
				z.sizeF += len;
			} else {
				z.onlyWater = false;
			}
		}

		WallObject wallObject = t.getWallObject();
		if (wallObject != null) {
			ModelOverride modelOverride = modelOverrideManager.getOverride(wallObject, worldPos);
			if (!modelOverride.hide) {
				estimateRenderableSize(z, wallObject.getRenderable1(), modelOverride);
				estimateRenderableSize(z, wallObject.getRenderable2(), modelOverride);
			}
		}

		DecorativeObject decorativeObject = t.getDecorativeObject();
		if (decorativeObject != null) {
			ModelOverride modelOverride = modelOverrideManager.getOverride(decorativeObject, worldPos);
			if (!modelOverride.hide) {
				estimateRenderableSize(z, decorativeObject.getRenderable(), modelOverride);
				estimateRenderableSize(z, decorativeObject.getRenderable2(), modelOverride);
			}
		}

		GroundObject groundObject = t.getGroundObject();
		if (groundObject != null) {
			ModelOverride modelOverride = modelOverrideManager.getOverride(groundObject, worldPos);
			if (!modelOverride.hide)
				estimateRenderableSize(z, groundObject.getRenderable(), modelOverride);
		}

		GameObject[] gameObjects = t.getGameObjects();
		for (GameObject gameObject : gameObjects) {
			if (gameObject == null || !gameObject.getSceneMinLocation().equals(t.getSceneLocation()))
				continue;

			if (ModelHash.isTemporaryObject(gameObject.getHash()))
				continue;

			ModelOverride modelOverride = modelOverrideManager.getOverride(gameObject, worldPos);
			if (modelOverride.hide)
				continue;

			estimateRenderableSize(z, gameObject.getRenderable(), modelOverride);
		}

		Tile bridge = t.getBridge();
		if (bridge != null)
			estimateZoneTileSize(ctx, z, bridge);
	}

	private void uploadZoneTile(
		ZoneSceneContext ctx,
		Zone zone,
		Tile t,
		boolean isBridge,
		boolean onlyWaterSurface,
		GpuIntBuffer vertexBuffer,
		GpuIntBuffer alphaBuffer,
		GpuIntBuffer textureBuffer
	) {
		var tilePoint = t.getSceneLocation();
		int tileExX = tilePoint.getX() + ctx.sceneOffset;
		int tileExY = tilePoint.getY() + ctx.sceneOffset;
		int tileZ = t.getRenderLevel();
		ctx.sceneToWorld(tilePoint.getX(), tilePoint.getY(), t.getPlane(), worldPos);

		if (ctx.currentArea != null && !isBridge && !ctx.currentArea.containsPoint(worldPos))
			return;

		boolean drawTile = renderCallbackManager.drawTile(ctx.scene, t);

		SceneTilePaint paint = t.getSceneTilePaint();
		if (paint != null && drawTile) {
			uploadTilePaint(
				ctx,
				t,
				paint,
				onlyWaterSurface,
				tileExX, tileExY, tileZ,
				vertexBuffer,
				textureBuffer,
				tilePoint.getX() * 128 - basex, tilePoint.getY() * 128 - basez
			);
		}

		SceneTileModel model = t.getSceneTileModel();
		if (model != null && drawTile)
			uploadTileModel(ctx, t, model, onlyWaterSurface, tileExX, tileExY, tileZ, basex, basez, vertexBuffer, textureBuffer);

		if (!onlyWaterSurface)
			uploadZoneTileRenderables(ctx, zone, t, vertexBuffer, alphaBuffer, textureBuffer);

		Tile bridge = t.getBridge();
		if (bridge != null)
			uploadZoneTile(ctx, zone, bridge, true, onlyWaterSurface, vertexBuffer, alphaBuffer, textureBuffer);
	}

	private void uploadZoneTileRenderables(
		ZoneSceneContext ctx,
		Zone zone,
		Tile t,
		GpuIntBuffer vertexBuffer,
		GpuIntBuffer alphaBuffer,
		GpuIntBuffer textureBuffer
	) {
		WallObject wallObject = t.getWallObject();
		if (wallObject != null && renderCallbackManager.drawObject(ctx.scene, wallObject)) {
			int uuid = ModelHash.packUuid(ModelHash.TYPE_WALL_OBJECT, wallObject.getId());
			Renderable renderable1 = wallObject.getRenderable1();
			uploadZoneRenderable(
				ctx,
				zone,
				t,
				renderable1,
				uuid,
				HDUtils.convertWallObjectOrientation(wallObject.getOrientationA()),
				0,
				wallObject.getX(),
				wallObject.getZ(),
				wallObject.getY(),
				-1,
				-1,
				-1,
				-1,
				wallObject.getId(),
				vertexBuffer,
				alphaBuffer,
				textureBuffer
			);

			Renderable renderable2 = wallObject.getRenderable2();
			uploadZoneRenderable(
				ctx,
				zone,
				t,
				renderable2,
				uuid,
				HDUtils.convertWallObjectOrientation(wallObject.getOrientationB()),
				0,
				wallObject.getX(),
				wallObject.getZ(),
				wallObject.getY(),
				-1,
				-1,
				-1,
				-1,
				wallObject.getId(),
				vertexBuffer,
				alphaBuffer,
				textureBuffer
			);
		}

		DecorativeObject decorativeObject = t.getDecorativeObject();
		if (decorativeObject != null && renderCallbackManager.drawObject(ctx.scene, decorativeObject)) {
			int uuid = ModelHash.packUuid(ModelHash.TYPE_DECORATIVE_OBJECT, decorativeObject.getId());
			int preOrientation = HDUtils.getModelPreOrientation(decorativeObject.getConfig());
			Renderable renderable = decorativeObject.getRenderable();
			uploadZoneRenderable(
				ctx,
				zone,
				t,
				renderable,
				uuid,
				preOrientation,
				0,
				decorativeObject.getX() + decorativeObject.getXOffset(),
				decorativeObject.getZ(),
				decorativeObject.getY() + decorativeObject.getYOffset(),
				-1,
				-1,
				-1,
				-1,
				decorativeObject.getId(),
				vertexBuffer,
				alphaBuffer,
				textureBuffer
			);

			Renderable renderable2 = decorativeObject.getRenderable2();
			uploadZoneRenderable(
				ctx,
				zone,
				t,
				renderable2,
				uuid,
				preOrientation,
				0,
				decorativeObject.getX(),
				decorativeObject.getZ(),
				decorativeObject.getY(),
				-1,
				-1,
				-1,
				-1,
				decorativeObject.getId(),
				vertexBuffer,
				alphaBuffer,
				textureBuffer
			);
		}

		GroundObject groundObject = t.getGroundObject();
		if (groundObject != null && renderCallbackManager.drawObject(ctx.scene, groundObject)) {
			Renderable renderable = groundObject.getRenderable();
			uploadZoneRenderable(
				ctx,
				zone,
				t,
				renderable,
				ModelHash.packUuid(ModelHash.TYPE_GROUND_OBJECT, groundObject.getId()),
				HDUtils.getModelPreOrientation(groundObject.getConfig()),
				0,
				groundObject.getX(), groundObject.getZ(), groundObject.getY(),
				-1,
				-1, -1,
				-1,
				groundObject.getId(),
				vertexBuffer,
				alphaBuffer,
				textureBuffer
			);
		}

		GameObject[] gameObjects = t.getGameObjects();
		for (GameObject gameObject : gameObjects) {
			if (gameObject == null || !renderCallbackManager.drawObject(ctx.scene, gameObject))
				continue;

			if (ModelHash.isTemporaryObject(gameObject.getHash()))
				continue;

			Point min = gameObject.getSceneMinLocation();
			if (!min.equals(t.getSceneLocation()))
				continue;

			Point max = gameObject.getSceneMaxLocation();
			Renderable renderable = gameObject.getRenderable();
			uploadZoneRenderable(
				ctx,
				zone,
				t,
				renderable,
				ModelHash.packUuid(ModelHash.TYPE_GAME_OBJECT, gameObject.getId()),
				HDUtils.getModelPreOrientation(gameObject.getConfig()),
				gameObject.getModelOrientation(),
				gameObject.getX(), gameObject.getZ(), gameObject.getY(),
				min.getX(),
				min.getY(), max.getX(),
				max.getY(),
				gameObject.getId(),
				vertexBuffer,
				alphaBuffer,
				textureBuffer
			);
		}
	}

	private void estimateRenderableSize(Zone z, Renderable r, ModelOverride modelOverride) {
		boolean mightHaveTransparency = modelOverride.mightHaveTransparency;
		Model m = null;
		if (r instanceof Model) {
			m = (Model) r;
		} else if (r instanceof DynamicObject) {
			var dynamic = (DynamicObject) r;
			m = dynamic.getModelZbuf();
			if (dynamic.getRecordedObjectComposition() != null)
				mightHaveTransparency = true;
		}
		if (m == null)
			return;

		int faceCount = m.getFaceCount();
		byte[] transparencies = m.getFaceTransparencies();
		short[] faceTextures = m.getFaceTextures();
		if (transparencies == null && faceTextures == null && !mightHaveTransparency) {
			z.sizeO += faceCount;
		} else {
			z.sizeO += faceCount;
			z.sizeA += faceCount;
		}
		z.sizeF += faceCount;
	}

	private void uploadZoneRenderable(
		ZoneSceneContext ctx,
		Zone zone,
		Tile tile,
		Renderable r,
		int uuid,
		int preOrientation,
		int orient,
		int x,
		int y,
		int z,
		int lx,
		int lz,
		int ux,
		int uz,
		int id,
		GpuIntBuffer opaqueBuffer,
		GpuIntBuffer alphaBuffer,
		GpuIntBuffer textureBuffer
	) {
		Model model;
		if (r instanceof Model) {
			model = (Model) r;
		} else if (r instanceof DynamicObject) {
			var dynamic = (DynamicObject) r;
			model = dynamic.getModelZbuf();

			if (model == null) {
				// The model will likely be drawn through drawDynamic, and may have an impostor
				zone.animatedDynamicObjectIds.add(id);
				return;
			}

			var composition = dynamic.getRecordedObjectComposition();
			if (composition != null)
				uuid = ModelHash.packUuid(ModelHash.TYPE_GAME_OBJECT, composition.getId());
		} else {
			return;
		}

		ModelOverride modelOverride = modelOverrideManager.getOverride(uuid, worldPos);
		if (modelOverride.hide)
			return;

		int alphaStart = alphaBuffer != null ? alphaBuffer.position() : 0;
		try {
			uploadStaticModel(
				ctx, tile, model, modelOverride, uuid,
				preOrientation, orient,
				x - basex, y, z - basez,
				opaqueBuffer,
				alphaBuffer,
				textureBuffer
			);
		} catch (Throwable ex) {
			log.warn(
				"Error uploading {} {} {} {} (ID {}), override=\"{}\", opaque={}, alpha={}",
				r instanceof DynamicObject ? "dynamic" : "static",
				ModelHash.getTypeName(ModelHash.getUuidType(uuid)),
				ModelHash.getUuidSubType(uuid),
				gamevalManager.getObjectName(id),
				id,
				modelOverride.description,
				opaqueBuffer,
				alphaBuffer,
				ex
			);
		}

		int alphaEnd = alphaBuffer != null ? alphaBuffer.position() : 0;
		if (alphaEnd > alphaStart) {
			if (lx > -1) {
				lx -= basex >> 7;
				lz -= basez >> 7;
				ux -= basex >> 7;
				uz -= basez >> 7;
				assert lx >= 0 : lx;
				assert lz >= 0 : lz;
				assert ux < 25 : ux; // largest object?
				assert uz < 25 : uz;
			}
			try {
				zone.addAlphaModel(
					plugin,
					materialManager,
					zone.glVaoA,
					zone.tboF.getTexId(),
					model, modelOverride, alphaStart, alphaEnd,
					x - basex, y, z - basez,
					lx, lz, ux, uz,
					rid, level, id
				);
			} catch (Throwable ex) {
				log.warn(
					"Error adding alpha model for {} {} {} {} (ID {}), override=\"{}\", opaque={}, alpha={}",
					r instanceof DynamicObject ? "dynamic" : "static",
					ModelHash.getTypeName(ModelHash.getUuidType(uuid)),
					ModelHash.getUuidSubType(uuid),
					gamevalManager.getObjectName(id),
					id,
					modelOverride.description,
					opaqueBuffer,
					alphaBuffer,
					ex
				);
			}
		}
	}

	@SuppressWarnings({ "UnnecessaryLocalVariable" })
	private void uploadTilePaint(
		ZoneSceneContext ctx,
		Tile tile,
		SceneTilePaint paint,
		boolean onlyWaterSurface,
		int tileExX, int tileExY, int tileZ,
		GpuIntBuffer vb,
		GpuIntBuffer fb,
		int lx,
		int lz
	) {
		int swColor = paint.getSwColor();
		int seColor = paint.getSeColor();
		int neColor = paint.getNeColor();
		int nwColor = paint.getNwColor();

		if (neColor == HIDDEN_HSL)
			return;

		TileOverride override = tileOverrideManager.getOverride(ctx, tile, worldPos);
		WaterType waterType = proceduralGenerator.seasonalWaterType(override, paint.getTexture());
		if (onlyWaterSurface && waterType == WaterType.NONE)
			return;

		ctx.filledTiles[tileExX][tileExY] |= (byte) (1 << tileZ);

		int swHeight = tileHeights[tileZ][tileExX][tileExY];
		int seHeight = tileHeights[tileZ][tileExX + 1][tileExY];
		int neHeight = tileHeights[tileZ][tileExX + 1][tileExY + 1];
		int nwHeight = tileHeights[tileZ][tileExX][tileExY + 1];
		int textureId = paint.getTexture();

		// 0,0
		final int lx0 = lx;
		final int lz0 = lz;

		// 1,0
		final int lx1 = lx + LOCAL_TILE_SIZE;
		final int lz1 = lz;

		// 1,1
		final int lx2 = lx + LOCAL_TILE_SIZE;
		final int lz2 = lz + LOCAL_TILE_SIZE;

		// 0,1
		final int lx3 = lx;
		final int lz3 = lz + LOCAL_TILE_SIZE;

		ProceduralGenerator.tileVertexKeys(ctx, tile, vertices, vertexKeys);
		int swVertexKey = vertexKeys[0];
		int seVertexKey = vertexKeys[1];
		int nwVertexKey = vertexKeys[2];
		int neVertexKey = vertexKeys[3];
		boolean neVertexIsOverlay = false;
		boolean nwVertexIsOverlay = false;
		boolean seVertexIsOverlay = false;
		boolean swVertexIsOverlay = false;

		int uvOrientation = 0;
		float uvScale = 1;

		Material swMaterial = Material.NONE;
		Material seMaterial = Material.NONE;
		Material neMaterial = Material.NONE;
		Material nwMaterial = Material.NONE;

		int[] swNormals = UP_NORMAL;
		int[] seNormals = UP_NORMAL;
		int[] neNormals = UP_NORMAL;
		int[] nwNormals = UP_NORMAL;

		int swTerrainData, seTerrainData, nwTerrainData, neTerrainData;
		swTerrainData = seTerrainData = nwTerrainData = neTerrainData = HDUtils.packTerrainData(true, 0, waterType, tileZ);

		if (!onlyWaterSurface) {
			swNormals = ctx.vertexTerrainNormals.getOrDefault(swVertexKey, swNormals);
			seNormals = ctx.vertexTerrainNormals.getOrDefault(seVertexKey, seNormals);
			neNormals = ctx.vertexTerrainNormals.getOrDefault(neVertexKey, neNormals);
			nwNormals = ctx.vertexTerrainNormals.getOrDefault(nwVertexKey, nwNormals);
		}

		if (waterType == WaterType.NONE) {
			if (textureId != -1) {
				var material = materialManager.fromVanillaTexture(textureId);
				// Disable tile overrides for newly introduced vanilla textures
				if (material.isFallbackVanillaMaterial)
					override = NONE;
				swMaterial = seMaterial = neMaterial = nwMaterial = material;
			}

			boolean useBlendedMaterialAndColor =
				plugin.configGroundBlending &&
				textureId == -1 &&
				!proceduralGenerator.useDefaultColor(tile, override);
			GroundMaterial groundMaterial = null;
			if (override != TileOverride.NONE) {
				groundMaterial = override.groundMaterial;
				uvOrientation = override.uvOrientation;
				uvScale = override.uvScale;
				if (!useBlendedMaterialAndColor) {
					swColor = override.modifyColor(swColor);
					seColor = override.modifyColor(seColor);
					nwColor = override.modifyColor(nwColor);
					neColor = override.modifyColor(neColor);
				}
				swHeight -= override.heightOffset;
				seHeight -= override.heightOffset;
				neHeight -= override.heightOffset;
				nwHeight -= override.heightOffset;
			} else if (textureId == -1) {
				// Fall back to the default ground material if the tile is untextured
				groundMaterial = override.groundMaterial;
			}

			if (useBlendedMaterialAndColor) {
				// get the vertices' colors and textures from hashmaps
				swColor = ctx.vertexTerrainColor.getOrDefault(swVertexKey, swColor);
				seColor = ctx.vertexTerrainColor.getOrDefault(seVertexKey, seColor);
				neColor = ctx.vertexTerrainColor.getOrDefault(neVertexKey, neColor);
				nwColor = ctx.vertexTerrainColor.getOrDefault(nwVertexKey, nwColor);

				if (plugin.configGroundTextures) {
					swMaterial = ctx.vertexTerrainTexture.getOrDefault(swVertexKey, swMaterial);
					seMaterial = ctx.vertexTerrainTexture.getOrDefault(seVertexKey, seMaterial);
					neMaterial = ctx.vertexTerrainTexture.getOrDefault(neVertexKey, neMaterial);
					nwMaterial = ctx.vertexTerrainTexture.getOrDefault(nwVertexKey, nwMaterial);
				}
			} else if (plugin.configGroundTextures && groundMaterial != null) {
				swMaterial = groundMaterial.getRandomMaterial(worldPos[0], worldPos[1], worldPos[2]);
				seMaterial = groundMaterial.getRandomMaterial(worldPos[0] + 1, worldPos[1], worldPos[2]);
				nwMaterial = groundMaterial.getRandomMaterial(worldPos[0], worldPos[1] + 1, worldPos[2]);
				neMaterial = groundMaterial.getRandomMaterial(worldPos[0] + 1, worldPos[1] + 1, worldPos[2]);
			}

			if (ctx.vertexIsOverlay.containsKey(neVertexKey) && ctx.vertexIsUnderlay.containsKey(neVertexKey))
				neVertexIsOverlay = true;
			if (ctx.vertexIsOverlay.containsKey(nwVertexKey) && ctx.vertexIsUnderlay.containsKey(nwVertexKey))
				nwVertexIsOverlay = true;
			if (ctx.vertexIsOverlay.containsKey(seVertexKey) && ctx.vertexIsUnderlay.containsKey(seVertexKey))
				seVertexIsOverlay = true;
			if (ctx.vertexIsOverlay.containsKey(swVertexKey) && ctx.vertexIsUnderlay.containsKey(swVertexKey))
				swVertexIsOverlay = true;
		} else if (onlyWaterSurface) {
			// set colors for the shoreline to create a foam effect in the water shader
			swColor = seColor = nwColor = neColor = 127;

			if (ctx.vertexIsWater.containsKey(swVertexKey) && ctx.vertexIsLand.containsKey(swVertexKey))
				swColor = 0;
			if (ctx.vertexIsWater.containsKey(seVertexKey) && ctx.vertexIsLand.containsKey(seVertexKey))
				seColor = 0;
			if (ctx.vertexIsWater.containsKey(nwVertexKey) && ctx.vertexIsLand.containsKey(nwVertexKey))
				nwColor = 0;
			if (ctx.vertexIsWater.containsKey(neVertexKey) && ctx.vertexIsLand.containsKey(neVertexKey))
				neColor = 0;

			if (seColor == 0 && nwColor == 0 && (neColor == 0 || swColor == 0))
				swColor = seColor = nwColor = neColor = 1 << 16; // Bias depth a bit if it's flush with underwater geometry
		} else {
			// Underwater geometry
			swColor = seColor = neColor = nwColor = UNDERWATER_HSL;

			if (plugin.configGroundTextures) {
				GroundMaterial groundMaterial = GroundMaterial.UNDERWATER_GENERIC;
				swMaterial = groundMaterial.getRandomMaterial(worldPos[0], worldPos[1], worldPos[2]);
				seMaterial = groundMaterial.getRandomMaterial(worldPos[0] + 1, worldPos[1], worldPos[2]);
				nwMaterial = groundMaterial.getRandomMaterial(worldPos[0], worldPos[1] + 1, worldPos[2]);
				neMaterial = groundMaterial.getRandomMaterial(worldPos[0] + 1, worldPos[1] + 1, worldPos[2]);
			}

			int swDepth = ctx.vertexUnderwaterDepth.getOrDefault(swVertexKey, 0);
			int seDepth = ctx.vertexUnderwaterDepth.getOrDefault(seVertexKey, 0);
			int nwDepth = ctx.vertexUnderwaterDepth.getOrDefault(nwVertexKey, 0);
			int neDepth = ctx.vertexUnderwaterDepth.getOrDefault(neVertexKey, 0);
			swHeight += swDepth;
			seHeight += seDepth;
			nwHeight += nwDepth;
			neHeight += neDepth;

			swTerrainData = HDUtils.packTerrainData(true, max(1, swDepth), waterType, tileZ);
			seTerrainData = HDUtils.packTerrainData(true, max(1, seDepth), waterType, tileZ);
			nwTerrainData = HDUtils.packTerrainData(true, max(1, nwDepth), waterType, tileZ);
			neTerrainData = HDUtils.packTerrainData(true, max(1, neDepth), waterType, tileZ);
		}

		int swMaterialData = swMaterial.packMaterialData(ModelOverride.NONE, UvType.GEOMETRY, swVertexIsOverlay);
		int seMaterialData = seMaterial.packMaterialData(ModelOverride.NONE, UvType.GEOMETRY, seVertexIsOverlay);
		int nwMaterialData = nwMaterial.packMaterialData(ModelOverride.NONE, UvType.GEOMETRY, nwVertexIsOverlay);
		int neMaterialData = neMaterial.packMaterialData(ModelOverride.NONE, UvType.GEOMETRY, neVertexIsOverlay);

		float uvcos = -uvScale, uvsin = 0;
		if (uvOrientation % 2048 != 0) {
			float rad = -uvOrientation * JAU_TO_RAD;
			uvcos = cos(rad) * -uvScale;
			uvsin = sin(rad) * -uvScale;
		}
		float uvx = worldPos[0];
		float uvy = worldPos[1];
		float tmp = uvx;
		uvx = fract(uvx * uvcos - uvy * uvsin);
		uvy = fract(tmp * uvsin + uvy * uvcos);

		int texturedFaceIdx = fb.putFace(
			neColor, nwColor, seColor,
			neMaterialData, nwMaterialData, seMaterialData,
			neTerrainData, nwTerrainData, seTerrainData
		);

		vb.putVertex(
			lx2, neHeight, lz2,
			uvx, uvy, 0,
			neNormals[0], neNormals[2], neNormals[1],
			texturedFaceIdx
		);

		vb.putVertex(
			lx3, nwHeight, lz3,
			uvx - uvcos, uvy - uvsin, 0,
			nwNormals[0], nwNormals[2], nwNormals[1],
			texturedFaceIdx
		);

		vb.putVertex(
			lx1, seHeight, lz1,
			uvx + uvsin, uvy - uvcos, 0,
			seNormals[0], seNormals[2], seNormals[1],
			texturedFaceIdx
		);

		texturedFaceIdx = fb.putFace(
			swColor, seColor, nwColor,
			swMaterialData, seMaterialData, nwMaterialData,
			swTerrainData, seTerrainData, nwTerrainData
		);

		vb.putVertex(
			lx0, swHeight, lz0,
			uvx - uvcos + uvsin, uvy - uvsin - uvcos, 0,
			swNormals[0], swNormals[2], swNormals[1],
			texturedFaceIdx
		);

		vb.putVertex(
			lx1, seHeight, lz1,
			uvx + uvsin, uvy - uvcos, 0,
			seNormals[0], seNormals[2], seNormals[1],
			texturedFaceIdx
		);

		vb.putVertex(
			lx3, nwHeight, lz3,
			uvx - uvcos, uvy - uvsin, 0,
			nwNormals[0], nwNormals[2], nwNormals[1],
			texturedFaceIdx
		);
	}

	private void uploadTileModel(
		ZoneSceneContext ctx,
		Tile tile,
		SceneTileModel model,
		boolean onlyWaterSurface,
		int tileExX, int tileExY, int tileZ,
		int basex, int basez,
		GpuIntBuffer vb,
		GpuIntBuffer fb
	) {
		final int[] triangleTextures = model.getTriangleTextureId();
		boolean isFallbackWater = false;
		if (triangleTextures != null) {
			for (int textureId : triangleTextures) {
				if (textureId != -1 && proceduralGenerator.seasonalWaterType(TileOverride.NONE, textureId) != WaterType.NONE) {
					isFallbackWater = true;
					break;
				}
			}
		}
		int overlayId = OVERLAY_FLAG | overlayIds[tileZ][tileExX][tileExY];
		int underlayId = underlayIds[tileZ][tileExX][tileExY];
		var overlayOverride = tileOverrideManager.getOverride(ctx, tile, worldPos, overlayId);
		var underlayOverride = tileOverrideManager.getOverride(ctx, tile, worldPos, underlayId);
		WaterType overlayWaterType = proceduralGenerator.seasonalWaterType(overlayOverride, 0);
		WaterType underlayWaterType = proceduralGenerator.seasonalWaterType(underlayOverride, 0);
		boolean isOverlayWater = overlayWaterType != WaterType.NONE;
		boolean isUnderlayWater = underlayWaterType != WaterType.NONE;
		if (onlyWaterSurface && !isFallbackWater && !isOverlayWater && !isUnderlayWater)
			return;

		ctx.filledTiles[tileExX][tileExY] |= (byte) (1 << tileZ);

		final int[] faceX = model.getFaceX();
		final int[] faceY = model.getFaceY();
		final int[] faceZ = model.getFaceZ();

		final int[] vertexX = model.getVertexX();
		final int[] vertexY = model.getVertexY();
		final int[] vertexZ = model.getVertexZ();

		final int[] triangleColorA = model.getTriangleColorA();
		final int[] triangleColorB = model.getTriangleColorB();
		final int[] triangleColorC = model.getTriangleColorC();

		final int faceCount = faceX.length;

		var sceneLoc = tile.getSceneLocation();
		int tileX = sceneLoc.getX();
		int tileY = sceneLoc.getY();

		for (int face = 0; face < faceCount; ++face) {
			int colorA = triangleColorA[face];
			int colorB = triangleColorB[face];
			int colorC = triangleColorC[face];
			if (colorA == HIDDEN_HSL)
				continue;

			int textureId = triangleTextures == null ? -1 : triangleTextures[face];
			boolean isOverlay = ProceduralGenerator.isOverlayFace(tile, face);
			var override = isOverlay ? overlayOverride : underlayOverride;
			WaterType waterType = proceduralGenerator.seasonalWaterType(override, textureId);
			boolean isWater = waterType != WaterType.NONE;
			if (onlyWaterSurface && !isWater)
				continue;

			final int vertex0 = faceX[face];
			final int vertex1 = faceY[face];
			final int vertex2 = faceZ[face];

			// vertexes are stored in scene local, convert to tile local
			int lx0 = vertexX[vertex0] - basex;
			int ly0 = vertexY[vertex0];
			int lz0 = vertexZ[vertex0] - basez;

			int lx1 = vertexX[vertex1] - basex;
			int ly1 = vertexY[vertex1];
			int lz1 = vertexZ[vertex1] - basez;

			int lx2 = vertexX[vertex2] - basex;
			int ly2 = vertexY[vertex2];
			int lz2 = vertexZ[vertex2] - basez;

			ProceduralGenerator.faceVertexKeys(tile, face, vertices, vertexKeys);
			ProceduralGenerator.faceLocalVertices(tile, face, vertices);

			int vertexKeyA = vertexKeys[0];
			int vertexKeyB = vertexKeys[1];
			int vertexKeyC = vertexKeys[2];

			boolean vertexAIsOverlay = false;
			boolean vertexBIsOverlay = false;
			boolean vertexCIsOverlay = false;

			Material materialA = Material.NONE;
			Material materialB = Material.NONE;
			Material materialC = Material.NONE;

			int uvOrientation = 0;
			float uvScale = 1;

			int[] normalsA = UP_NORMAL;
			int[] normalsB = UP_NORMAL;
			int[] normalsC = UP_NORMAL;

			int terrainDataA, terrainDataB, terrainDataC;
			terrainDataA = terrainDataB = terrainDataC = HDUtils.packTerrainData(true, 0, waterType, tileZ);

			if (!onlyWaterSurface) {
				normalsA = ctx.vertexTerrainNormals.getOrDefault(vertexKeyA, normalsA);
				normalsB = ctx.vertexTerrainNormals.getOrDefault(vertexKeyB, normalsB);
				normalsC = ctx.vertexTerrainNormals.getOrDefault(vertexKeyC, normalsC);
			}

			if (!isWater) {
				if (textureId != -1) {
					var material = materialManager.fromVanillaTexture(textureId);
					// Disable tile overrides for newly introduced vanilla textures
					if (material.isFallbackVanillaMaterial)
						override = NONE;
					materialA = materialB = materialC = material;
				}

				GroundMaterial groundMaterial = null;

				boolean useBlendedMaterialAndColor =
					plugin.configGroundBlending &&
					textureId == -1 &&
					!(isOverlay && proceduralGenerator.useDefaultColor(tile, override));
				if (override != TileOverride.NONE) {
					groundMaterial = override.groundMaterial;
					uvOrientation = override.uvOrientation;
					uvScale = override.uvScale;
					if (!useBlendedMaterialAndColor) {
						colorA = override.modifyColor(colorA);
						colorB = override.modifyColor(colorB);
						colorC = override.modifyColor(colorC);
					}
				} else if (textureId == -1) {
					// Fall back to the default ground material if the tile is untextured
					groundMaterial = override.groundMaterial;
				}

				if (useBlendedMaterialAndColor) {
					// get the vertices' colors and textures from hashmaps
					colorA = ctx.vertexTerrainColor.getOrDefault(vertexKeyA, colorA);
					colorB = ctx.vertexTerrainColor.getOrDefault(vertexKeyB, colorB);
					colorC = ctx.vertexTerrainColor.getOrDefault(vertexKeyC, colorC);

					if (plugin.configGroundTextures) {
						materialA = ctx.vertexTerrainTexture.getOrDefault(vertexKeyA, materialA);
						materialB = ctx.vertexTerrainTexture.getOrDefault(vertexKeyB, materialB);
						materialC = ctx.vertexTerrainTexture.getOrDefault(vertexKeyC, materialC);
					}
				} else if (plugin.configGroundTextures && groundMaterial != null) {
					materialA = groundMaterial.getRandomMaterial(
						worldPos[0] + (vertices[0][0] >> LOCAL_COORD_BITS),
						worldPos[1] + (vertices[0][1] >> LOCAL_COORD_BITS),
						worldPos[2]
					);
					materialB = groundMaterial.getRandomMaterial(
						worldPos[0] + (vertices[1][0] >> LOCAL_COORD_BITS),
						worldPos[1] + (vertices[1][1] >> LOCAL_COORD_BITS),
						worldPos[2]
					);
					materialC = groundMaterial.getRandomMaterial(
						worldPos[0] + (vertices[2][0] >> LOCAL_COORD_BITS),
						worldPos[1] + (vertices[2][1] >> LOCAL_COORD_BITS),
						worldPos[2]
					);
				}
			} else if (onlyWaterSurface) {
				// set colors for the shoreline to create a foam effect in the water shader
				colorA = colorB = colorC = 127;
				if (ctx.vertexIsWater.containsKey(vertexKeyA) && ctx.vertexIsLand.containsKey(vertexKeyA))
					colorA = 0;
				if (ctx.vertexIsWater.containsKey(vertexKeyB) && ctx.vertexIsLand.containsKey(vertexKeyB))
					colorB = 0;
				if (ctx.vertexIsWater.containsKey(vertexKeyC) && ctx.vertexIsLand.containsKey(vertexKeyC))
					colorC = 0;
				if (colorA == 0 && colorB == 0 && colorC == 0)
					colorA = colorB = colorC = 1 << 16; // Bias depth a bit if it's flush with underwater geometry
			} else {
				// Underwater geometry
				colorA = colorB = colorC = UNDERWATER_HSL;

				if (plugin.configGroundTextures) {
					GroundMaterial groundMaterial = GroundMaterial.UNDERWATER_GENERIC;
					materialA = groundMaterial.getRandomMaterial(
						worldPos[0] + (vertices[0][0] >> LOCAL_COORD_BITS),
						worldPos[1] + (vertices[0][1] >> LOCAL_COORD_BITS),
						worldPos[2]
					);
					materialB = groundMaterial.getRandomMaterial(
						worldPos[0] + (vertices[1][0] >> LOCAL_COORD_BITS),
						worldPos[1] + (vertices[1][1] >> LOCAL_COORD_BITS),
						worldPos[2]
					);
					materialC = groundMaterial.getRandomMaterial(
						worldPos[0] + (vertices[2][0] >> LOCAL_COORD_BITS),
						worldPos[1] + (vertices[2][1] >> LOCAL_COORD_BITS),
						worldPos[2]
					);
				}

				int depthA = ctx.vertexUnderwaterDepth.getOrDefault(vertexKeyA, 0);
				int depthB = ctx.vertexUnderwaterDepth.getOrDefault(vertexKeyB, 0);
				int depthC = ctx.vertexUnderwaterDepth.getOrDefault(vertexKeyC, 0);
				ly0 += depthA;
				ly1 += depthB;
				ly2 += depthC;

				terrainDataA = HDUtils.packTerrainData(true, max(1, depthA), waterType, tileZ);
				terrainDataB = HDUtils.packTerrainData(true, max(1, depthB), waterType, tileZ);
				terrainDataC = HDUtils.packTerrainData(true, max(1, depthC), waterType, tileZ);
			}

			if (ctx.vertexIsOverlay.containsKey(vertexKeyA) && ctx.vertexIsUnderlay.containsKey(vertexKeyA))
				vertexAIsOverlay = true;
			if (ctx.vertexIsOverlay.containsKey(vertexKeyB) && ctx.vertexIsUnderlay.containsKey(vertexKeyB))
				vertexBIsOverlay = true;
			if (ctx.vertexIsOverlay.containsKey(vertexKeyC) && ctx.vertexIsUnderlay.containsKey(vertexKeyC))
				vertexCIsOverlay = true;

			ly0 -= override.heightOffset;
			ly1 -= override.heightOffset;
			ly2 -= override.heightOffset;

			int materialDataA = materialA.packMaterialData(ModelOverride.NONE, UvType.GEOMETRY, vertexAIsOverlay);
			int materialDataB = materialB.packMaterialData(ModelOverride.NONE, UvType.GEOMETRY, vertexBIsOverlay);
			int materialDataC = materialC.packMaterialData(ModelOverride.NONE, UvType.GEOMETRY, vertexCIsOverlay);

			float uvcos = -uvScale, uvsin = 0;
			if (uvOrientation % 2048 != 0) {
				float rad = -uvOrientation * JAU_TO_RAD;
				uvcos = cos(rad) * -uvScale;
				uvsin = sin(rad) * -uvScale;
			}

			float uvx = fract(worldPos[0] * uvcos - worldPos[1] * uvsin);
			float uvy = fract(worldPos[0] * uvsin + worldPos[1] * uvcos);

			float dx, dz;
			dx = (float) lx0 / LOCAL_TILE_SIZE - tileX;
			dz = (float) lz0 / LOCAL_TILE_SIZE - tileY;
			float uvAx = uvx + dx * uvcos - dz * uvsin;
			float uvAy = uvy + dx * uvsin + dz * uvcos;
			dx = (float) lx1 / LOCAL_TILE_SIZE - tileX;
			dz = (float) lz1 / LOCAL_TILE_SIZE - tileY;
			float uvBx = uvx + dx * uvcos - dz * uvsin;
			float uvBy = uvy + dx * uvsin + dz * uvcos;
			dx = (float) lx2 / LOCAL_TILE_SIZE - tileX;
			dz = (float) lz2 / LOCAL_TILE_SIZE - tileY;
			float uvCx = uvx + dx * uvcos - dz * uvsin;
			float uvCy = uvy + dx * uvsin + dz * uvcos;

			int texturedFaceIdx = fb.putFace(
				colorA, colorB, colorC,
				materialDataA, materialDataB, materialDataC,
				terrainDataA, terrainDataB, terrainDataC
			);

			vb.putVertex(
				lx0, ly0, lz0,
				uvAx, uvAy, 0,
				normalsA[0], normalsA[2], normalsA[1],
				texturedFaceIdx
			);

			vb.putVertex(
				lx1, ly1, lz1,
				uvBx, uvBy, 0,
				normalsB[0], normalsB[2], normalsB[1],
				texturedFaceIdx
			);

			vb.putVertex(
				lx2, ly2, lz2,
				uvCx, uvCy, 0,
				normalsC[0], normalsC[2], normalsC[1],
				texturedFaceIdx
			);
		}
	}

	// scene upload
	private int uploadStaticModel(
		ZoneSceneContext ctx,
		Tile tile,
		Model model,
		ModelOverride modelOverride,
		int uuid,
		int preOrientation, int orientation,
		int x, int y, int z,
		GpuIntBuffer opaqueBuffer,
		GpuIntBuffer alphaBuffer,
		GpuIntBuffer textureBuffer
	) {
		if (writeCache == null)
			writeCache = new VertexWriteCache.Collection();
		writeCache.setOutputBuffers(opaqueBuffer, alphaBuffer, textureBuffer);

		final int[][][] tileHeights = ctx.scene.getTileHeights();
		final int faceCount = model.getFaceCount();
		final int vertexCount = model.getVerticesCount();

		final float[] vertexX = model.getVerticesX();
		final float[] vertexY = model.getVerticesY();
		final float[] vertexZ = model.getVerticesZ();

		final int[] indices1 = model.getFaceIndices1();
		final int[] indices2 = model.getFaceIndices2();
		final int[] indices3 = model.getFaceIndices3();

		final short[] unlitFaceColors = plugin.configUnlitFaceColors ? model.getUnlitFaceColors() : null;
		final int[] color1s = model.getFaceColors1();
		final int[] color2s = model.getFaceColors2();
		final int[] color3s = model.getFaceColors3();

		final int[] xVertexNormals = model.getVertexNormalsX();
		final int[] yVertexNormals = model.getVertexNormalsY();
		final int[] zVertexNormals = model.getVertexNormalsZ();
		final boolean modelHasNormals = xVertexNormals != null && yVertexNormals != null && zVertexNormals != null;

		final short[] faceTextures = model.getFaceTextures();
		final byte[] textureFaces = model.getTextureFaces();

		final byte[] bias = model.getFaceBias();
		final byte[] transparencies = model.getFaceTransparencies();
		final float modelHeight = model.getModelHeight();

		int orientSin = 0;
		int orientCos = 0;
		if (orientation != 0) {
			orientation = mod(orientation, 2048);
			orientSin = SINE[orientation];
			orientCos = COSINE[orientation];
		}

		for (int v = 0, vertexOffset = 0; v < vertexCount; ++v) {
			int vx = (int) vertexX[v];
			int vy = (int) vertexY[v];
			int vz = (int) vertexZ[v];
			float heightFrac = modelOverride.terrainVertexSnap ? abs(vy / modelHeight) : 0.0f;

			if (orientation != 0) {
				int x0 = vx;
				vx = vz * orientSin + x0 * orientCos >> 16;
				vz = vz * orientCos - x0 * orientSin >> 16;
			}

			vx += x;
			vy += y;
			vz += z;

			if (modelOverride.terrainVertexSnap && heightFrac <= modelOverride.terrainVertexSnapThreshold) {
				int plane = tile.getRenderLevel();
				int tileExX = clamp(ctx.sceneOffset + ((vx + basex) / 128), 0, EXTENDED_SCENE_SIZE - 1);
				int tileExY = clamp(ctx.sceneOffset + ((vz + basez) / 128), 0, EXTENDED_SCENE_SIZE - 1);

				float h00 = tileHeights[plane][tileExX][tileExY];
				float h10 = tileHeights[plane][tileExX + 1][tileExY];
				float h01 = tileHeights[plane][tileExX][tileExY + 1];
				float h11 = tileHeights[plane][tileExX + 1][tileExY + 1];

				float hx0 = mix(h00, h10, (vx % 128.0f) / 128.0f);
				float hx1 = mix(h01, h11, (vx % 128.0f) / 128.0f);
				float h = mix(hx0, hx1, (vz % 128.0f) / 128.0f);

				float blend = divide(heightFrac, modelOverride.terrainVertexSnapThreshold);
				vy = (int) mix(h, vy, blend);
			}

			modelLocalI[vertexOffset++] = vx;
			modelLocalI[vertexOffset++] = vy;
			modelLocalI[vertexOffset++] = vz;
		}

		boolean isVanillaTextured = faceTextures != null;
		boolean isVanillaUVMapped =
			isVanillaTextured && // Vanilla UV mapped models don't always have sensible UVs for untextured faces
			textureFaces != null;

		final Material baseMaterial = modelOverride.baseMaterial;
		final Material textureMaterial = modelOverride.textureMaterial;

		int len = 0;
		for (int face = 0; face < faceCount; ++face) {
			int color1 = color1s[face];
			int color2 = color2s[face];
			int color3 = color3s[face];

			if (color3 == -1) {
				color2 = color3 = color1;
			} else if (color3 == -2) {
				continue;
			}

			if (unlitFaceColors != null)
				color1 = color2 = color3 = unlitFaceColors[face] & 0xFFFF;

			UvType uvType = UvType.GEOMETRY;
			Material material = baseMaterial;
			ModelOverride faceOverride = modelOverride;

			int transparency = transparencies != null ? transparencies[face] & 0xFF : 0;
			int textureId = isVanillaTextured ? faceTextures[face] : -1;
			boolean isTextured = textureId != -1;
			if (isTextured) {
				uvType = UvType.VANILLA;
				if (textureMaterial != Material.NONE) {
					material = textureMaterial;
				} else {
					material = materialManager.fromVanillaTexture(textureId);
					if (modelOverride.materialOverrides != null) {
						var override = modelOverride.materialOverrides.get(material);
						if (override != null) {
							faceOverride = override;
							material = faceOverride.textureMaterial;
						}
					}
				}
			} else if (modelOverride.colorOverrides != null) {
				final int ahsl = (0xFF - transparency) << 16 | color1;
				final var override = modelOverride.testColorOverrides(ahsl);
				if (override != null) {
					faceOverride = override;
					material = faceOverride.baseMaterial;
				}
			}

			if (faceOverride.hide)
				continue;

			final int triangleA = indices1[face];
			final int triangleB = indices2[face];
			final int triangleC = indices3[face];

			int vertexOffset = triangleA * 3;
			final int vx1 = modelLocalI[vertexOffset];
			final int vy1 = modelLocalI[vertexOffset + 1];
			final int vz1 = modelLocalI[vertexOffset + 2];

			vertexOffset = triangleB * 3;
			final int vx2 = modelLocalI[vertexOffset];
			final int vy2 = modelLocalI[vertexOffset + 1];
			final int vz2 = modelLocalI[vertexOffset + 2];

			vertexOffset = triangleC * 3;
			final int vx3 = modelLocalI[vertexOffset];
			final int vy3 = modelLocalI[vertexOffset + 1];
			final int vz3 = modelLocalI[vertexOffset + 2];

			boolean keepShading = isTextured;
			if (isTextured) {
				// Without overriding the color for textured faces, vanilla shading remains pretty noticeable even after
				// the approximate reversal above. Ardougne rooftops is a good example, where vanilla shading results in a
				// weird-looking tint. The brightness clamp afterward is required to reduce the over-exposure introduced.
				color1 = color2 = color3 = 90;
			} else {
				// Hide fake shadows or lighting that is often baked into models by making the fake shadow transparent
				if (plugin.configHideFakeShadows && modelOverride.hideVanillaShadows && HDUtils.isBakedGroundShading(model, face))
					continue;

				if (modelOverride.inheritTileColorType != InheritTileColorType.NONE) {
					final Scene scene = ctx.scene;
					SceneTileModel tileModel = tile.getSceneTileModel();
					SceneTilePaint tilePaint = tile.getSceneTilePaint();

					if (tilePaint != null || tileModel != null) {
						// No point in inheriting tilepaint color if the ground tile does not have a color, for example above a cave wall
						if (
							tilePaint != null &&
							tilePaint.getTexture() == -1 &&
							tilePaint.getRBG() != 0 &&
							tilePaint.getNeColor() != HIDDEN_HSL
						) {
							// Since tile colors are guaranteed to have the same hue and saturation per face,
							// we can blend without converting from HSL to RGB
							int averageColor =
								(tilePaint.getSwColor() + tilePaint.getNwColor() + tilePaint.getNeColor() + tilePaint.getSeColor()) / 4;

							var override = tileOverrideManager.getOverride(ctx, tile);
							averageColor = override.modifyColor(averageColor);
							color1 = color2 = color3 = averageColor;

							// Let the shader know vanilla shading reversal should be skipped for this face
							keepShading = true;
						} else if (tileModel != null && tileModel.getTriangleTextureId() == null) {
							int faceColorIndex = -1;
							for (int i = 0; i < tileModel.getTriangleColorA().length; i++) {
								boolean isOverlay = ProceduralGenerator.isOverlayFace(tile, i);
								// Use underlay if the tile does not have an overlay, useful for rocks in cave corners.
								if (modelOverride.inheritTileColorType == InheritTileColorType.UNDERLAY
									|| tileModel.getModelOverlay() == 0) {
									// pulling the color from UNDERLAY is more desirable for green grass tiles
									// OVERLAY pulls in path color which is not desirable for grass next to paths
									if (!isOverlay) {
										faceColorIndex = i;
										break;
									}
								} else if (modelOverride.inheritTileColorType == InheritTileColorType.OVERLAY) {
									if (isOverlay) {
										// OVERLAY used in dirt/path/house tile color blend better with rubbles/rocks
										faceColorIndex = i;
										break;
									}
								}
							}

							if (faceColorIndex != -1) {
								int color = tileModel.getTriangleColorA()[faceColorIndex];
								if (color != HIDDEN_HSL) {
									var scenePos = tile.getSceneLocation();
									int tileX = scenePos.getX();
									int tileY = scenePos.getY();
									int tileZ = tile.getRenderLevel();
									int tileExX = tileX + ctx.sceneOffset;
									int tileExY = tileY + ctx.sceneOffset;
									int tileId = modelOverride.inheritTileColorType == InheritTileColorType.OVERLAY ?
										OVERLAY_FLAG | scene.getOverlayIds()[tileZ][tileExX][tileExY] :
										scene.getUnderlayIds()[tileZ][tileExX][tileExY];
									var override = tileOverrideManager.getOverride(ctx, tile, worldPos, tileId);
									color = override.modifyColor(color);
									color1 = color2 = color3 = color;

									// Let the shader know vanilla shading reversal should be skipped for this face
									keepShading = true;
								}
							}
						}
					}
				}

				if (plugin.configLegacyTzHaarReskin && modelOverride.tzHaarRecolorType != TzHaarRecolorType.NONE) {
					// The legacy TzHaar reskin is not thread-safe
					synchronized (proceduralGenerator) {
						int[] tzHaarRecolored = ProceduralGenerator.recolorTzHaar(
							modelOverride,
							model,
							face,
							color1,
							color2,
							color3
						);
						color1 = tzHaarRecolored[0];
						color2 = tzHaarRecolored[1];
						color3 = tzHaarRecolored[2];
					}
				}
			}

			int textureFace = textureFaces != null ? textureFaces[face] : -1;
			if (material != Material.NONE) {
				uvType = faceOverride.uvType;
				if (uvType == UvType.VANILLA || (textureId != -1 && faceOverride.retainVanillaUvs))
					uvType = isVanillaUVMapped && textureFace != -1 ? UvType.VANILLA : UvType.GEOMETRY;
			}

			final int materialData = material.packMaterialData(faceOverride, uvType, false);

			final float[] faceUVs;
			if (uvType == UvType.VANILLA && textureId != -1) {
				computeFaceUvsInline(faceUVs = modelUvs, model, textureFace, triangleA, triangleB, triangleC);
			} else if (uvType != UvType.GEOMETRY) {
				faceOverride.fillUvsForFace(faceUVs = modelUvs, model, preOrientation, uvType, face, workingSpace);
			} else {
				faceUVs = GEOMETRY_UVS;
			}

			final boolean shouldRotateNormals;
			boolean shouldCalculateFaceNormal;
			if (!modelHasNormals || faceOverride.flatNormals || !plugin.configPreserveVanillaNormals && color3s[face] == -1) {
				shouldRotateNormals = false;
				shouldCalculateFaceNormal = true;
			} else {
				shouldRotateNormals = orientation != 0;
				shouldCalculateFaceNormal = (modelNormals[0] = xVertexNormals[triangleA]) == 0;
				shouldCalculateFaceNormal &= (modelNormals[1] = yVertexNormals[triangleA]) == 0;
				shouldCalculateFaceNormal &= (modelNormals[2] = zVertexNormals[triangleA]) == 0;
				shouldCalculateFaceNormal &= (modelNormals[3] = xVertexNormals[triangleB]) == 0;
				shouldCalculateFaceNormal &= (modelNormals[4] = yVertexNormals[triangleB]) == 0;
				shouldCalculateFaceNormal &= (modelNormals[5] = zVertexNormals[triangleB]) == 0;
				shouldCalculateFaceNormal &= (modelNormals[6] = xVertexNormals[triangleC]) == 0;
				shouldCalculateFaceNormal &= (modelNormals[7] = yVertexNormals[triangleC]) == 0;
				shouldCalculateFaceNormal &= (modelNormals[8] = zVertexNormals[triangleC]) == 0;
			}

			if (shouldCalculateFaceNormal) {
				calculateFaceNormal(
					modelNormals,
					vx1, vy1, vz1,
					vx2, vy2, vz2,
					vx3, vy3, vz3
				);
			}

			if (plugin.configUndoVanillaShading && modelOverride.undoVanillaShading && !keepShading) {
				color1 = undoVanillaShading(color1, plugin.configLegacyGreyColors, modelNormals[0], modelNormals[1], modelNormals[2]);
				color2 = undoVanillaShading(color2, plugin.configLegacyGreyColors, modelNormals[3], modelNormals[4], modelNormals[5]);
				color3 = undoVanillaShading(color3, plugin.configLegacyGreyColors, modelNormals[6], modelNormals[7], modelNormals[8]);
			}

			if (shouldRotateNormals)
				rotateNormals(modelNormals, orientSin, orientCos);

			int depthBias = faceOverride.depthBias != -1 ? faceOverride.depthBias :
				bias == null ? 0 : bias[face] & 0xFF;
			int packedAlphaBiasHsl = transparency << 24 | depthBias << 16;
			boolean hasAlpha = material.hasTransparency || transparency != 0;
			final VertexWriteCache vb = writeCache.useAlphaBuffer && hasAlpha ? writeCache.alpha : writeCache.opaque;
			final VertexWriteCache tb = writeCache.opaqueTex;

			color1 |= packedAlphaBiasHsl;
			color2 |= packedAlphaBiasHsl;
			color3 |= packedAlphaBiasHsl;

			final int texturedFaceIdx = tb.putFace(
				color1, color2, color3,
				materialData, materialData, materialData,
				0, 0, 0
			);

			vb.putStaticVertex(
				vx1, vy1, vz1,
				faceUVs[0], faceUVs[1], faceUVs[2],
				modelNormals[0], modelNormals[1], modelNormals[2],
				texturedFaceIdx
			);

			vb.putStaticVertex(
				vx2, vy2, vz2,
				faceUVs[4], faceUVs[5], faceUVs[6],
				modelNormals[3], modelNormals[4], modelNormals[5],
				texturedFaceIdx
			);

			vb.putStaticVertex(
				vx3, vy3, vz3,
				faceUVs[8], faceUVs[9], faceUVs[10],
				modelNormals[6], modelNormals[7], modelNormals[8],
				texturedFaceIdx
			);
			len += 3;
		}
		writeCache.flush();
		return len;
	}

	public boolean preprocessTempModel(
		Projection proj,
		float[][] sceneFrustumPlanes,
		int[] faceDistances,
		PrimitiveIntArray visibleFaces,
		PrimitiveIntArray culledFaces,
		boolean isModelPartiallyVisible,
		ModelOverride modelOverride,
		Model model,
		boolean sortAllFaces,
		int orientation,
		float x, float y, float z
	) {
		final int vertexCount = model.getVerticesCount();

		final float[] verticesX = model.getVerticesX();
		final float[] verticesY = model.getVerticesY();
		final float[] verticesZ = model.getVerticesZ();

		final float[] modelLocal = this.modelLocal;
		final int[] modelLocalI = this.modelLocalI;
		final float[] modelProjected = this.modelProjected;
		final boolean[] visibility = this.visibility;
		final float[] projected = this.projected;

		if (isModelPartiallyVisible)
			Arrays.fill(visibility, 0, vertexCount, true);

		// Identity orient, will result in no rotation
		float orientSinf = 0;
		float orientCosf = 1;

		if (orientation != 0) {
			orientation = mod(orientation, 2048);
			orientSinf = SINE[orientation] / 65536f;
			orientCosf = COSINE[orientation] / 65536f;
		}

		boolean shouldSort = true;
		boolean allVertsVisible = true;
		for (int v = 0, vertexOffset = 0; v < vertexCount; ++v) {
			float vertexX = verticesX[v];
			float vertexY = verticesY[v];
			float vertexZ = verticesZ[v];

			if (orientation != 0) {
				final float x0 = vertexX;
				vertexX = vertexZ * orientSinf + x0 * orientCosf;
				vertexZ = vertexZ * orientCosf - x0 * orientSinf;
			}

			vertexX += x;
			vertexY += y;
			vertexZ += z;

			proj.project(vertexX, vertexY, vertexZ, projected);

			if (isModelPartiallyVisible) {
				// Ignore near & far plane, only test against the side planes
				if (!(visibility[v] = HDUtils.isPointWithinFrustum(vertexX, vertexY, vertexZ, sceneFrustumPlanes, 4)))
					allVertsVisible = false;
			}

			final float pX = projected[0];
			final float pY = projected[1];
			float pZ = projected[2];

			// Vertex is behind the camera and therefore isn't visible
			if (pZ <= 0.0f) {
				if (pZ == 0.0f)
					pZ = -1e-6f; // Avoid division by zero
				if (isModelPartiallyVisible)
					visibility[v] = allVertsVisible = false;
			}

			modelLocal[vertexOffset] = vertexX;
			modelLocalI[vertexOffset] = Float.floatToIntBits(vertexX);
			modelProjected[vertexOffset] = pX / pZ;
			vertexOffset++;

			modelLocal[vertexOffset] = vertexY;
			modelLocalI[vertexOffset] = Float.floatToIntBits(vertexY);
			modelProjected[vertexOffset] = pY / pZ;
			vertexOffset++;

			modelLocal[vertexOffset] = vertexZ;
			modelLocalI[vertexOffset] = Float.floatToIntBits(vertexZ);
			modelProjected[vertexOffset] = pZ;
			vertexOffset++;

			shouldSort &= pZ >= 50;
		}

		visibleFaces.reset();
		culledFaces.reset();

		final int triangleCount = model.getFaceCount();
		visibleFaces.ensureCapacity(triangleCount);
		culledFaces.ensureCapacity(triangleCount);

		final int[] color3s = model.getFaceColors3();
		final int[] indices1 = model.getFaceIndices1();
		final int[] indices2 = model.getFaceIndices2();
		final int[] indices3 = model.getFaceIndices3();
		final byte[] transparencies = model.getFaceTransparencies();
		final short[] faceTextures = model.getFaceTextures();
		final byte[] textureFaces = model.getTextureFaces();

		final Material baseMaterial = modelOverride.baseMaterial;
		final Material textureMaterial = modelOverride.textureMaterial;

		final boolean isVanillaTextured = faceTextures != null;
		final boolean isVanillaUVMapped =
			isVanillaTextured && // Vanilla UV mapped models don't always have sensible UVs for untextured faces
			textureFaces != null;

		final int zero = (int) proj.project(x, y, z, projected)[2];
		final int radius = model.getRadius();
		final byte modelTransparency = model.getTransparency();

		tempModelAlphaFaces = 0;
		for (int f = 0; f < triangleCount; f++) {
			if (color3s[f] == -2)
				continue;

			int transparency = readFaceTransparency(modelTransparency, transparencies, f);
			if (transparency == 255)
				continue;

			// Hide fake shadows or lighting that is often baked into models by making the fake shadow transparent
			if (plugin.configHideFakeShadows && modelOverride.hideVanillaShadows && HDUtils.isBakedGroundShading(model, f))
				continue;

			UvType uvType = UvType.GEOMETRY;
			Material material = baseMaterial;
			ModelOverride faceOverride = modelOverride;

			final int textureId = isVanillaTextured ? faceTextures[f] : -1;
			if (textureId != -1) {
				uvType = UvType.VANILLA;
				if (textureMaterial != Material.NONE) {
					material = textureMaterial;
				} else {
					material = materialManager.fromVanillaTexture(textureId);
					if (modelOverride.materialOverrides != null) {
						var override = modelOverride.materialOverrides.get(material);
						if (override != null) {
							faceOverride = override;
							material = faceOverride.textureMaterial;
						}
					}
				}
			} else if (modelOverride.colorOverrides != null) {
				final int ahsl = (0xFF - transparency) << 16 | model.getFaceColors1()[f];
				final var override = modelOverride.testColorOverrides(ahsl);
				if (override != null) {
					faceOverride = override;
					material = faceOverride.baseMaterial;
				}
			}

			if (faceOverride.hide)
				continue;

			if (material != Material.NONE) {
				uvType = faceOverride.uvType;
				if (uvType == UvType.VANILLA || (textureId != -1 && faceOverride.retainVanillaUvs)) {
					final int textureFace = textureFaces != null ? textureFaces[f] : -1;
					uvType = isVanillaUVMapped && textureFace != -1 ? UvType.VANILLA : UvType.GEOMETRY;
				}
			}

			faceOverrides[f] = faceOverride;
			faceMaterials[f] = material;
			faceUVTypes[f] = uvType;

			int offsetA = indices1[f];
			int offsetB = indices2[f];
			int offsetC = indices3[f];

			if (!allVertsVisible && !visibility[offsetA] && !visibility[offsetB] && !visibility[offsetC]) {
				// TODO: If a triangle is large enough to encompass the entire screen, this will need an additional plane test
				culledFaces.put(f);
				continue;
			}

			offsetA *= 3;
			offsetB *= 3;
			offsetC *= 3;

			// Face is completely behind the projection view
			final float aX = modelProjected[offsetA];
			final float aY = modelProjected[offsetA + 1];

			final float bX = modelProjected[offsetB];
			final float bY = modelProjected[offsetB + 1];

			final float cX = modelProjected[offsetC];
			final float cY = modelProjected[offsetC + 1];

			// back face culling
			if ((aX - bX) * (cY - bY) - (cX - bX) * (aY - bY) <= 0) {
				culledFaces.put(f);
				continue;
			}

			if (material.hasTransparency || transparency != 0)
				tempModelAlphaFaces++;

			// store distance for face sorting
			if (faceDistances != null) {
				if (shouldSort && (sortAllFaces || material.hasTransparency || transparency != 0)) {
					final float aZ = modelProjected[offsetA + 2];
					final float bZ = modelProjected[offsetB + 2];
					final float cZ = modelProjected[offsetC + 2];

					faceDistances[f] = radius + ((int) ((aZ + bZ + cZ) / 3.0f) - zero);
				} else {
					faceDistances[f] = Integer.MIN_VALUE;
				}
			}

			visibleFaces.put(f);
		}

		return shouldSort;
	}

	// temp draw
	public void uploadTempModel(
		PrimitiveIntArray faces,
		Model model,
		ModelOverride modelOverride,
		int preOrientation,
		int orientation,
		boolean isShadow,
		DynamicModelVAO.View opaqueView,
		DynamicModelVAO.View alphaView
	) {
		if (writeCache == null)
			writeCache = new VertexWriteCache.Collection();
		writeCache.setOutputBuffers(
			opaqueView.vbo.getBuffer(),
			alphaView.vbo.getBuffer(),
			opaqueView.tbo.getBuffer(),
			alphaView.tbo.getBuffer()
		);

		final int[] indices1 = model.getFaceIndices1();
		final int[] indices2 = model.getFaceIndices2();
		final int[] indices3 = model.getFaceIndices3();

		final short[] unlitFaceColors = plugin.configUnlitFaceColors ? model.getUnlitFaceColors() : null;
		final int[] color1s = model.getFaceColors1();
		final int[] color2s = model.getFaceColors2();
		final int[] color3s = model.getFaceColors3();

		final int[] xVertexNormals = model.getVertexNormalsX();
		final int[] yVertexNormals = model.getVertexNormalsY();
		final int[] zVertexNormals = model.getVertexNormalsZ();

		final byte[] transparencies = model.getFaceTransparencies();
		final short[] faceTextures = model.getFaceTextures();
		final byte[] textureFaces = model.getTextureFaces();
		final byte[] bias = model.getFaceBias();
		final int[] faceNormals = isShadow ? EMPTY_NORMALS : modelNormals;

		final boolean hasBias = bias != null;
		final boolean modelHasNormals =
			model.getVertexNormalsX() != null &&
			model.getVertexNormalsY() != null &&
			model.getVertexNormalsZ() != null;

		final byte overrideAmount = model.getOverrideAmount();
		final byte overrideHue = model.getOverrideHue();
		final byte overrideSat = model.getOverrideSaturation();
		final byte overrideLum = model.getOverrideLuminance();
		final byte modelTransparency = model.getTransparency();

		final boolean isVanillaTextured = faceTextures != null;

		int orientSin = 0;
		int orientCos = 0;
		if (orientation != 0) {
			orientation = mod(orientation, 2048);
			orientSin = SINE[orientation];
			orientCos = COSINE[orientation];
		}

		final int faceCount = faces.length;
		for (int f = 0; f < faceCount; ++f) {
			final int face = faces.array[f];

			int color1 = color1s[face];
			int color2 = color2s[face];
			int color3 = color3s[face];

			if (unlitFaceColors != null)
				color1 = color2 = color3 = unlitFaceColors[face] & 0xFFFF;
			else if (color3 == -1)
				color2 = color3 = color1;

			int transparency = readFaceTransparency(modelTransparency, transparencies, face);
			final int textureFace = textureFaces != null ? textureFaces[face] : -1;
			final int textureId = isVanillaTextured ? faceTextures[face] : -1;
			final UvType uvType = faceUVTypes[face];
			final Material material = faceMaterials[face];
			final ModelOverride faceOverride = faceOverrides[face];

			if (textureId != -1)
				color1 = color2 = color3 = 90;

			final int materialData = material.packMaterialData(faceOverride, uvType, false);

			final int triangleA = indices1[face];
			final int vertexOffsetA = triangleA * 3;

			final int triangleB = indices2[face];
			final int vertexOffsetB = triangleB * 3;

			final int triangleC = indices3[face];
			final int vertexOffsetC = triangleC * 3;

			final float[] faceUVs;
			if (uvType == UvType.VANILLA && textureId != -1) {
				computeFaceUvsInline(faceUVs = modelUvs, model, textureFace, triangleA, triangleB, triangleC);
			} else if (uvType != UvType.GEOMETRY) {
				faceOverride.fillUvsForFace(faceUVs = modelUvs, model, preOrientation, uvType, face, workingSpace);
			} else {
				faceUVs = GEOMETRY_UVS;
			}

			if (!isShadow) {
				final boolean shouldRotateNormals;
				boolean shouldCalculateFaceNormal;
				if (!modelHasNormals || faceOverride.flatNormals || (!plugin.configPreserveVanillaNormals && color3s[face] == -1)) {
					shouldRotateNormals = false;
					shouldCalculateFaceNormal = true;
				} else {
					shouldRotateNormals = orientation != 0;
					shouldCalculateFaceNormal = (modelNormals[0] = xVertexNormals[triangleA]) == 0;
					shouldCalculateFaceNormal &= (modelNormals[1] = yVertexNormals[triangleA]) == 0;
					shouldCalculateFaceNormal &= (modelNormals[2] = zVertexNormals[triangleA]) == 0;
					shouldCalculateFaceNormal &= (modelNormals[3] = xVertexNormals[triangleB]) == 0;
					shouldCalculateFaceNormal &= (modelNormals[4] = yVertexNormals[triangleB]) == 0;
					shouldCalculateFaceNormal &= (modelNormals[5] = zVertexNormals[triangleB]) == 0;
					shouldCalculateFaceNormal &= (modelNormals[6] = xVertexNormals[triangleC]) == 0;
					shouldCalculateFaceNormal &= (modelNormals[7] = yVertexNormals[triangleC]) == 0;
					shouldCalculateFaceNormal &= (modelNormals[8] = zVertexNormals[triangleC]) == 0;
				}

				if (shouldCalculateFaceNormal) {
					calculateFaceNormal(
						faceNormals,
						modelLocal[vertexOffsetA], modelLocal[vertexOffsetA + 1], modelLocal[vertexOffsetA + 2],
						modelLocal[vertexOffsetB], modelLocal[vertexOffsetB + 1], modelLocal[vertexOffsetB + 2],
						modelLocal[vertexOffsetC], modelLocal[vertexOffsetC + 1], modelLocal[vertexOffsetC + 2]
					);
				}

				if (plugin.configUndoVanillaShading && modelOverride.undoVanillaShading) {
					color1 = undoVanillaShading(color1, plugin.configLegacyGreyColors, faceNormals[0], faceNormals[1], faceNormals[2]);
					color2 = undoVanillaShading(color2, plugin.configLegacyGreyColors, faceNormals[3], faceNormals[4], faceNormals[5]);
					color3 = undoVanillaShading(color3, plugin.configLegacyGreyColors, faceNormals[6], faceNormals[7], faceNormals[8]);
				}

				if (shouldRotateNormals && !shouldCalculateFaceNormal)
					rotateNormals(faceNormals, orientSin, orientCos);
			}

			// HSL override is not applied to textured faces
			if (overrideAmount > 0 && (!isVanillaTextured || faceTextures[face] == -1)) {
				color1 = interpolateHSL(color1, overrideHue, overrideSat, overrideLum, overrideAmount);
				color2 = interpolateHSL(color2, overrideHue, overrideSat, overrideLum, overrideAmount);
				color3 = interpolateHSL(color3, overrideHue, overrideSat, overrideLum, overrideAmount);
			}

			final int depthBias = faceOverride.depthBias != -1 ? faceOverride.depthBias :
				hasBias ? bias[face] & 0xFF : 0;
			final int packedAlphaBiasHsl = transparency << 24 | depthBias << 16;
			final boolean hasAlpha = material.hasTransparency || transparency != 0;

			color1 |= packedAlphaBiasHsl;
			color2 |= packedAlphaBiasHsl;
			color3 |= packedAlphaBiasHsl;

			final VertexWriteCache vb, tb;
			if (writeCache.useAlphaBuffer && hasAlpha) {
				vb = writeCache.alpha;
				tb = writeCache.alphaTex;
			} else {
				vb = writeCache.opaque;
				tb = writeCache.opaqueTex;
			}

			color1 |= packedAlphaBiasHsl;
			color2 |= packedAlphaBiasHsl;
			color3 |= packedAlphaBiasHsl;

			final int texturedFaceIdx = tb.putFace(
				color1, color2, color3,
				materialData, materialData, materialData,
				0, 0, 0
			);

			vb.putVertex(
				modelLocalI[vertexOffsetA], modelLocalI[vertexOffsetA + 1], modelLocalI[vertexOffsetA + 2],
				faceUVs[0], faceUVs[1], faceUVs[2],
				faceNormals[0], faceNormals[1], faceNormals[2],
				texturedFaceIdx
			);
			vb.putVertex(
				modelLocalI[vertexOffsetB], modelLocalI[vertexOffsetB + 1], modelLocalI[vertexOffsetB + 2],
				faceUVs[4], faceUVs[5], faceUVs[6],
				faceNormals[3], faceNormals[4], faceNormals[5],
				texturedFaceIdx
			);
			vb.putVertex(
				modelLocalI[vertexOffsetC], modelLocalI[vertexOffsetC + 1], modelLocalI[vertexOffsetC + 2],
				faceUVs[8], faceUVs[9], faceUVs[10],
				faceNormals[6], faceNormals[7], faceNormals[8],
				texturedFaceIdx
			);
		}

		writeCache.flush();
	}

	public static void calculateFaceNormal(
		int[] out,
		float vx1, float vy1, float vz1,
		float vx2, float vy2, float vz2,
		float vx3, float vy3, float vz3
	) {
		float e0_x = vx2 - vx1;
		float e0_y = vy2 - vy1;
		float e0_z = vz2 - vz1;

		float e1_x = vx3 - vx1;
		float e1_y = vy3 - vy1;
		float e1_z = vz3 - vz1;

		float nx = e0_y * e1_z - e0_z * e1_y;
		float ny = e0_z * e1_x - e0_x * e1_z;
		float nz = e0_x * e1_y - e0_y * e1_x;

		float length = (float) Math.sqrt(nx * nx + ny * ny + nz * nz);
		nx /= length;
		ny /= length;
		nz /= length;

		out[0] = out[3] = out[6] = (int) (nx * 2048);
		out[1] = out[4] = out[7] = (int) (ny * 2048);
		out[2] = out[5] = out[8] = (int) (nz * 2048);
	}

	public static int interpolateHSL(int hsl, byte hue2, byte sat2, byte lum2, byte lerp) {
		int hue = hsl >> 10 & 63;
		int sat = hsl >> 7 & 7;
		int lum = hsl & 127;
		int lerpInt = lerp & 255;
		if (hue2 != -1)
			hue += lerpInt * (hue2 - hue) >> 7;
		if (sat2 != -1)
			sat += lerpInt * (sat2 - sat) >> 7;
		if (lum2 != -1)
			lum += lerpInt * (lum2 - lum) >> 7;
		return (hue << 10 | sat << 7 | lum) & 65535;
	}

	public static void computeFaceUvsInline(
		float[] out,
		Model model,
		int textureFace,
		int triangleA,
		int triangleB,
		int triangleC
	) {
		final float[] vx = model.getVerticesX();
		final float[] vy = model.getVerticesY();
		final float[] vz = model.getVerticesZ();

		final int tf = textureFace & 0xFF;

		// v1
		int idx = model.getTexIndices1()[tf];
		final float v1x = vx[idx];
		final float v1y = vy[idx];
		final float v1z = vz[idx];

		// v2
		idx = model.getTexIndices2()[tf];
		final float v2x = vx[idx] - v1x;
		final float v2y = vy[idx] - v1y;
		final float v2z = vz[idx] - v1z;

		// v3
		idx = model.getTexIndices3()[tf];
		final float v3x = vx[idx] - v1x;
		final float v3y = vy[idx] - v1y;
		final float v3z = vz[idx] - v1z;

		// n = v2 x v3
		final float px = v2y * v3z - v2z * v3y;
		final float py = v2z * v3x - v2x * v3z;
		final float pz = v2x * v3y - v2y * v3x;

		// ---------- U axis ----------
		float tx = v3y * pz - v3z * py;
		float ty = v3z * px - v3x * pz;
		float tz = v3x * py - v3y * px;

		float inv = rcp(tx * v2x + ty * v2y + tz * v2z);

		float dx = vx[triangleA] - v1x;
		float dy = vy[triangleA] - v1y;
		float dz = vz[triangleA] - v1z;
		out[0] = (tx * dx + ty * dy + tz * dz) * inv;

		dx = vx[triangleB] - v1x;
		dy = vy[triangleB] - v1y;
		dz = vz[triangleB] - v1z;
		out[4] = (tx * dx + ty * dy + tz * dz) * inv;

		dx = vx[triangleC] - v1x;
		dy = vy[triangleC] - v1y;
		dz = vz[triangleC] - v1z;
		out[8] = (tx * dx + ty * dy + tz * dz) * inv;

		// ---------- V axis ----------
		tx = v2y * pz - v2z * py;
		ty = v2z * px - v2x * pz;
		tz = v2x * py - v2y * px;

		inv = rcp(tx * v3x + ty * v3y + tz * v3z);

		dx = vx[triangleA] - v1x;
		dy = vy[triangleA] - v1y;
		dz = vz[triangleA] - v1z;
		out[1] = (tx * dx + ty * dy + tz * dz) * inv;

		dx = vx[triangleB] - v1x;
		dy = vy[triangleB] - v1y;
		dz = vz[triangleB] - v1z;
		out[5] = (tx * dx + ty * dy + tz * dz) * inv;

		dx = vx[triangleC] - v1x;
		dy = vy[triangleC] - v1y;
		dz = vz[triangleC] - v1z;
		out[9] = (tx * dx + ty * dy + tz * dz) * inv;

		// ---------- W axis Unused ----------
		out[2] = out[6] = out[10] = 0f;
	}

	public static int undoVanillaShading(
		int color, boolean legacyGreyColors,
		int nx, int ny, int nz
	) {
		return undoVanillaShading(color, legacyGreyColors, nx * nx + ny * ny + nz * nz, nx + ny + nz);
	}

	public static int undoVanillaShading(
		int color, boolean legacyGreyColors,
		float nx, float ny, float nz
	) {
		return undoVanillaShading(color, legacyGreyColors, nx * nx + ny * ny + nz * nz, nx + ny + nz);
	}

	private static int undoVanillaShading(
		int color, boolean legacyGreyColors,
		float len, float norm
	) {
		//int h = color >> 10 & 0x3F; Unused only S & L need unpacking
		int s = (color >> 7) & 0x7;
		int l = color & 0x7F;

		// Approximately invert vanilla shading by brightening vertices that were likely darkened by vanilla based on
		// vertex normals. This process is error-prone, as not all models are lit by vanilla with the same light
		// direction, and some models even have baked lighting built into the model itself. In some cases, increasing
		// brightness in this way leads to overly bright colors, so we are forced to cap brightness at a relatively
		// low value for it to look acceptable in most cases.
		final float colorAdjust = BASE_LIGHTEN - l + (l < IGNORE_LOW_LIGHTNESS ? 0f : (l - IGNORE_LOW_LIGHTNESS) * LIGHTNESS_MULTIPLIER);

		// Normals are currently unrotated, so we don't need to do any rotation for this
		if (len > 0f) {
			final float invLen = rcp(sqrt(len));
			final float lightDotNormal = norm * 0.57735026f * invLen;
			if (lightDotNormal > 0f)
				l += (int) (lightDotNormal * colorAdjust);
		}

		// Clamp brightness as detailed above
		l = min(l, legacyGreyColors ? 55 : MAX_BRIGHTNESS_LOOKUP_TABLE[s]);

		// Preserve H, replace S & L
		return (color & 0xFC00) | (s << 7) | l;
	}

	private static int readFaceTransparency(byte modelTransparency, byte[] transparencies, int f) {
		// Based on https://github.com/runelite/runelite/commit/a88ac64d5a154020cdc21612fc0f1eb32aa8d0f8#diff-2495d11499767f573d041baf080ee6b50dddd325e37b34a402f4c23efc3c2324R464-R478
		if (modelTransparency == -1)
			return 255;

		int t = modelTransparency & 255;
		int faceTransparency = transparencies != null ? transparencies[f] & 0xFF : 0;
		if (t > 0 && faceTransparency < 253) {
			int a = (253 - faceTransparency) * t >> 8;
			assert (faceTransparency & 255) == faceTransparency;
			return faceTransparency + a;
		}

		return faceTransparency;
	}

	public static void rotateNormals(int[] normals, int orientSin, int orientCos) {
		int nx = normals[0], nz = normals[2];
		normals[0] = (nz * orientSin + nx * orientCos) >> 16;
		normals[2] = (nz * orientCos - nx * orientSin) >> 16;

		nx = normals[3];
		nz = normals[5];
		normals[3] = (nz * orientSin + nx * orientCos) >> 16;
		normals[5] = (nz * orientCos - nx * orientSin) >> 16;

		nx = normals[6];
		nz = normals[8];
		normals[6] = (nz * orientSin + nx * orientCos) >> 16;
		normals[8] = (nz * orientCos - nx * orientSin) >> 16;
	}

	@Override
	public void close() {
		clear();
		POOL.recycle(this);
	}
}

package rs117.hd.renderer.zone;

import com.google.inject.Injector;
import java.util.ArrayList;
import java.util.Arrays;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.api.hooks.*;
import net.runelite.client.callback.RenderCallbackManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import rs117.hd.HdPlugin;
import rs117.hd.HdPluginConfig;
import rs117.hd.config.ShadowMode;
import rs117.hd.overlays.FrameTimer;
import rs117.hd.overlays.Timer;
import rs117.hd.scene.ModelOverrideManager;
import rs117.hd.scene.model_overrides.ModelOverride;
import rs117.hd.utils.HDUtils;
import rs117.hd.utils.ModelHash;
import rs117.hd.utils.collections.ConcurrentPool;
import rs117.hd.utils.collections.PrimitiveIntArray;

import static net.runelite.api.Perspective.*;
import static net.runelite.api.hooks.DrawCallbacks.*;
import static rs117.hd.HdPlugin.PROCESSOR_COUNT;
import static rs117.hd.renderer.zone.WorldViewContext.VAO_ALPHA;
import static rs117.hd.renderer.zone.WorldViewContext.VAO_OPAQUE;
import static rs117.hd.renderer.zone.WorldViewContext.VAO_PLAYER;
import static rs117.hd.renderer.zone.WorldViewContext.VAO_SHADOW;
import static rs117.hd.utils.MathUtils.*;

@Slf4j
@Singleton
public class ModelStreamingManager {
	public static final ConcurrentPool<PrimitiveIntArray> FACE_INDICES = new ConcurrentPool<>(PrimitiveIntArray::new);
	public static final int RL_RENDER_THREADS = 2;

	@Inject
	private Injector injector;

	@Inject
	private Client client;

	@Inject
	private EventBus eventBus;

	@Inject
	private RenderCallbackManager renderCallbackManager;

	@Inject
	private HdPlugin plugin;

	@Inject
	private HdPluginConfig config;

	@Inject
	private SceneManager sceneManager;

	@Inject
	private ModelOverrideManager modelOverrideManager;

	@Inject
	private FrameTimer frameTimer;

	@Inject
	private ZoneRenderer renderer;

	private final ArrayList<AsyncCachedModel> pending = new ArrayList<>();
	private final StreamingContext[] streamingContexts = new StreamingContext[RL_RENDER_THREADS + 1];
	private int numRenderThreads = -1;

	static final class StreamingContext {
		final int[] worldPos = new int[3];
		final float[] objectWorldPos = new float[4];
		int renderableCount;
	}

	public void initialize() {
		for (int i = 0; i < streamingContexts.length; i++)
			streamingContexts[i] = injector.getInstance(StreamingContext.class);

		if (useMultithreading())
			AsyncCachedModel.initialize(injector, config.asyncModelCacheSizeMiB() * MiB);

		eventBus.register(this);
		updateRenderThreads();
	}

	public void destroy() {
		ensureAsyncUploadsComplete(null);

		eventBus.unregister(this);
		AsyncCachedModel.destroy();
		Arrays.fill(streamingContexts, null);
		numRenderThreads = -1;
	}

	public void reinitialize() {
		destroy();
		initialize();
	}

	StreamingContext context() {
		return streamingContexts[0];
	}

	StreamingContext context(int renderThreadId) {
		return streamingContexts[renderThreadId + 1];
	}

	private boolean useMultithreading() {
		return config.multithreadedModelProcessing() && PROCESSOR_COUNT > 1;
	}

	private void updateRenderThreads() {
		assert client.isClientThread();
		// Render threads will act as suppliers into the job system, so RL_RENDER_THREADS + the client thread
		int renderThreads = useMultithreading() && !plugin.isPowerSaving ? RL_RENDER_THREADS : 0;
		if (renderThreads != numRenderThreads) {
			int gpuFlags = plugin.gpuFlags & ~DrawCallbacks.RENDER_THREADS(RENDER_THREADS_MASK);
			client.setGpuFlags(gpuFlags | DrawCallbacks.RENDER_THREADS(renderThreads));
			numRenderThreads = renderThreads;
		}
	}

	@Subscribe
	public void onBeforeRender(BeforeRender event) {
		for (int i = 0; i < streamingContexts.length; i++)
			streamingContexts[i].renderableCount = 0;

		updateRenderThreads();
	}

	public int getDrawnDynamicRenderableCount() {
		int count = 0;
		for (int i = 0; i < streamingContexts.length; i++)
			count += streamingContexts[i].renderableCount;
		return count;
	}

	public void drawTemp(
		int renderThreadId,
		Projection projection,
		Scene scene,
		TileObject tileObject,
		Renderable r,
		Model m,
		int orient,
		int x,
		int y,
		int z
	) {
		WorldViewContext root = sceneManager.getRoot();
		WorldViewContext ctx = sceneManager.getContext(scene);
		if (root == null || ctx == null ||
			!sceneManager.isRoot(ctx) && ctx.isLoading ||
			!renderCallbackManager.drawObject(scene, tileObject))
			return;

		int offset = ctx.sceneContext.sceneOffset >> 3;
		int zx = (x >> 10) + offset;
		int zz = (z >> 10) + offset;
		Zone zone = ctx.zones[zx][zz];

		if (!zone.initialized)
			return;

		final StreamingContext streamingContext = context(renderThreadId);
		final float[] objectWorldPos = vec4(streamingContext.objectWorldPos, x, y, z, 1.0f);
		if (ctx.uboWorldViewStruct != null)
			ctx.uboWorldViewStruct.project(objectWorldPos);

		final int uuid;
		if (r instanceof DynamicObject) {
			int id = tileObject.getId();
			int impostorId = root.sceneContext.animatedDynamicObjectImpostors.getOrDefault(id, id);
			uuid = ModelHash.packUuid(ModelHash.getType(tileObject.getHash()), impostorId);

			// Cull dynamic models based on detail draw distance
			float squaredDistance = renderer.sceneCamera.squaredDistanceTo(objectWorldPos[0], objectWorldPos[1], objectWorldPos[2]);
			int detailDrawDistanceTiles = plugin.configDetailDrawDistance * LOCAL_TILE_SIZE;
			if (squaredDistance > detailDrawDistanceTiles * detailDrawDistanceTiles && modelOverrideManager.allowDetailCulling(uuid))
				return;
		} else {
			uuid = ModelHash.generateUuid(client, tileObject.getHash(), r);
		}

		// Hide everything outside the current area if area hiding is enabled
		if (ctx.sceneContext.currentArea != null && scene.getWorldViewId() == WorldView.TOPLEVEL) {
			var base = ctx.sceneContext.sceneBase;
			assert base != null;
			boolean inArea = ctx.sceneContext.currentArea.containsPoint(
				base[0] + ((int) objectWorldPos[0] >> Perspective.LOCAL_COORD_BITS),
				base[1] + ((int) objectWorldPos[2] >> Perspective.LOCAL_COORD_BITS),
				base[2] + client.getTopLevelWorldView().getPlane()
			);
			if (!inArea)
				return;
		}

		ctx.sceneContext.localToWorld(x, z, tileObject.getPlane(), streamingContext.worldPos);
		ModelOverride modelOverride = modelOverrideManager.getOverride(uuid, streamingContext.worldPos);
		if (modelOverride.hide)
			return;

		m.calculateBoundsCylinder();

		final int modelClassification = renderer.sceneCamera.classifySphere(
			objectWorldPos[0], objectWorldPos[1], objectWorldPos[2], m.getRadius());
		boolean isOffScreen = modelClassification == -1;
		// Additional Culling checks to help reduce dynamic object perf impact when off-screen
		if (isOffScreen && (
			!modelOverride.castShadows ||
			!renderer.directionalShadowCasterVolume.intersectsPoint(
				(int) objectWorldPos[0],
				(int) objectWorldPos[1],
				(int) objectWorldPos[2]
			)
		)) {
			return;
		}
		streamingContext.renderableCount++;

		final boolean hasAlpha =
			(m.getTransparency() != 0 || m.getFaceTransparencies() != null || modelOverride.mightHaveTransparency) &&
			(!sceneManager.isRoot(ctx) || zone.inSceneFrustum);
		final Zone.AlphaModel alphaModel = hasAlpha ?
			zone.requestTempAlphaModel(
				modelOverride,
				Math.min(ctx.maxLevel, tileObject.getPlane()),
				x & 1023,
				y - (r instanceof Actor ? r.getModelHeight() : 0), // order players over objects?
				z & 1023
			) : null;

		final int drawIndex = renderThreadId != -1 ? -1 : ctx.obtainDrawIndex(r instanceof Player ? VAO_PLAYER : VAO_OPAQUE);
		final boolean isModelPartiallyVisible = sceneManager.isRoot(ctx) && modelClassification == 0;
		final AsyncCachedModel asyncModelCache = obtainAvailableAsyncCachedModel(renderThreadId >= 0);
		if (asyncModelCache != null) {
			// Fast path, buffer the model into the job queue to unblock rl internals
			asyncModelCache.queue(
				ctx,
				projection,
				tileObject,
				r,
				modelOverride,
				m,
				zone,
				alphaModel,
				isModelPartiallyVisible,
				drawIndex,
				orient,
				x, y, z,
				this::uploadTempModelAsync
			);
			return;
		}

		uploadTempModel(
			ctx,
			projection,
			tileObject,
			r,
			modelOverride,
			m,
			zone,
			alphaModel,
			isModelPartiallyVisible,
			-1,
			drawIndex,
			orient,
			x, y, z
		);
	}

	private void uploadTempModelAsync(
		WorldViewContext ctx,
		Projection projection,
		TileObject tileObject,
		Renderable renderable,
		ModelOverride modelOverride,
		Model model,
		Zone zone,
		Zone.AlphaModel alphaModel,
		boolean isModelPartiallyVisible,
		int drawIndex,
		int orientation,
		int x, int y, int z
	) {
		final long t = System.nanoTime();
		uploadTempModel(
			ctx,
			projection,
			tileObject,
			renderable,
			modelOverride,
			model,
			zone,
			alphaModel,
			isModelPartiallyVisible,
			-1,
			drawIndex,
			orientation,
			x, y, z
		);
		frameTimer.add(renderable instanceof Actor ? Timer.DRAW_TEMP_ASYNC : Timer.DRAW_DYNAMIC_ASYNC, System.nanoTime() - t);
	}

	public void uploadTempModel(
		WorldViewContext ctx,
		Projection projection,
		@Nullable TileObject tileObject,
		Renderable renderable,
		ModelOverride modelOverride,
		Model m,
		@Nullable Zone zone,
		@Nullable Zone.AlphaModel alphaModel,
		boolean isModelPartiallyVisible,
		int vaoType,
		int drawIndex,
		int orient,
		float x, float y, float z
	) {
		final PrimitiveIntArray visibleFaces = FACE_INDICES.acquire();
		final PrimitiveIntArray culledFaces = FACE_INDICES.acquire();

		boolean isActor = renderable instanceof Actor;
		boolean isPlayer = renderable instanceof Player;
		final int renderMode = renderable.getRenderMode();
		boolean shouldSort =
			m.getTransparency() != 0 ||
			m.getFaceTransparencies() != null ||
			modelOverride.mightHaveTransparency ||
			renderable instanceof Player ||
			(
				renderMode != Renderable.RENDERMODE_UNSORTED &&
				renderMode != Renderable.RENDERMODE_DEFAULT &&
				renderMode != Renderable.RENDERMODE_UNSORTED_NO_DEPTH
			);

		try (
			SceneUploader sceneUploader = SceneUploader.POOL.acquire();
			FacePrioritySorter facePrioritySorter = shouldSort ? FacePrioritySorter.POOL.acquire() : null
		) {
			shouldSort &= sceneUploader.preprocessTempModel(
				projection,
				plugin.cameraFrustum,
				shouldSort ? facePrioritySorter.faceDistances : null,
				visibleFaces,
				culledFaces,
				isModelPartiallyVisible,
				modelOverride,
				m,
				isPlayer,
				orient,
				x, y, z
			);

			final int preOrientation = HDUtils.getModelPreOrientation(HDUtils.getObjectConfig(tileObject));
			final boolean isSquashed = ctx.uboWorldViewStruct != null && ctx.uboWorldViewStruct.isSquashed();
			if (shouldSort && !isSquashed)
				facePrioritySorter.sortModelFaces(visibleFaces, m, !isActor);

			if (culledFaces.length > 0 &&
				modelOverride.castShadows &&
				plugin.configShadowMode != ShadowMode.OFF &&
				(!sceneManager.isRoot(ctx) || zone != null && zone.inShadowFrustum)
			) {
				final DynamicModelVAO.View shadowView = ctx.beginDraw(VAO_SHADOW, culledFaces.length);
				sceneUploader.uploadTempModel(
					culledFaces,
					m,
					modelOverride,
					preOrientation,
					orient,
					true,
					shadowView,
					shadowView
				);
				shadowView.end();
			}

			if (visibleFaces.length > 0) {
				final int alphaFaceCount = alphaModel != null ? sceneUploader.tempModelAlphaFaces : 0;
				final int opaqueFaceCount = visibleFaces.length - alphaFaceCount;
				assert opaqueFaceCount >= 0 && alphaFaceCount >= 0 : "Invalid face counts: " + opaqueFaceCount + ", " + alphaFaceCount;

				// opaque player faces have their own vao and are drawn in a separate pass from normal opaque faces
				// because they are not depth tested. transparent player faces don't need their own vao because normal
				// transparent faces are already not depth tested
				if (vaoType == -1)
					vaoType = isPlayer ? VAO_PLAYER : VAO_OPAQUE;
				final DynamicModelVAO.View opaqueView = ctx.beginDraw(vaoType, drawIndex, opaqueFaceCount);
				final DynamicModelVAO.View alphaView = alphaFaceCount > 0 ? ctx.beginDraw(VAO_ALPHA, alphaFaceCount) : opaqueView;

				sceneUploader.uploadTempModel(
					visibleFaces,
					m,
					modelOverride,
					preOrientation,
					orient,
					isSquashed,
					opaqueView,
					alphaView
				);

				if (opaqueView != alphaView && alphaView.getEndOffset() > alphaView.getStartOffset()) {
					alphaModel.setView(alphaView);
					alphaView.end();
				}
				opaqueView.end();
			}
		} catch (Exception e) {
			log.error("Error rendering dynamic object", e);
		} finally {
			FACE_INDICES.recycle(visibleFaces);
			FACE_INDICES.recycle(culledFaces);
		}
	}

	public void ensureAsyncUploadsComplete(@Nullable Zone zone) {
		if (AsyncCachedModel.POOL == null)
			return;

		frameTimer.begin(Timer.MODEL_UPLOAD_COMPLETE);
		pending.clear();
		AsyncCachedModel model;
		while ((model = (zone != null ? zone.pendingModelJobs.poll() : AsyncCachedModel.INFLIGHT.poll())) != null)
			pending.add(model);

		AsyncCachedModel pendingModel;
		boolean shouldBlock = false, hasStolen = false;
		int idx = 0;
		while (!pending.isEmpty()) {
			pendingModel = pending.get(idx);

			if (pendingModel.isQueued() && pendingModel.canStart() && pendingModel.processModel()) {
				pending.remove(idx);
				hasStolen = true;
			}

			if (shouldBlock && pendingModel.waitForCompletion(10))
				pending.remove(idx);

			if (pending.isEmpty())
				break;

			idx = (idx + 1) % pending.size();
			if (idx == 0 && !shouldBlock) {
				// We've wrapped around to the start, check if any work was stolen.
				// If no work was stolen, the next iteration we should block since we'll never be able to steal
				shouldBlock = !hasStolen;
				hasStolen = false;
			}
		}

		frameTimer.end(Timer.MODEL_UPLOAD_COMPLETE);
	}


	private AsyncCachedModel obtainAvailableAsyncCachedModel(boolean shouldBlock) {
		if (AsyncCachedModel.POOL == null || numRenderThreads <= 0)
			return null;

		return shouldBlock ? AsyncCachedModel.POOL.acquireBlocking(5000) : AsyncCachedModel.POOL.acquire();
	}
}

package rs117.hd.renderer.zone;

import java.nio.IntBuffer;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.function.ToIntFunction;
import javax.annotation.Nullable;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import org.lwjgl.system.MemoryStack;
import rs117.hd.HdPlugin;
import rs117.hd.scene.MaterialManager;
import rs117.hd.scene.SceneContext;
import rs117.hd.scene.materials.Material;
import rs117.hd.scene.model_overrides.ModelOverride;
import rs117.hd.utils.Camera;
import rs117.hd.utils.CommandBuffer;
import rs117.hd.utils.Destructible;
import rs117.hd.utils.DestructibleHandler;
import rs117.hd.utils.HDUtils;
import rs117.hd.utils.buffer.GLBuffer;
import rs117.hd.utils.buffer.GLTextureBuffer;

import static org.lwjgl.opengl.GL33C.*;
import static rs117.hd.HdPlugin.GL_CAPS;
import static rs117.hd.HdPlugin.SUPPORTS_INDIRECT_DRAW;
import static rs117.hd.HdPlugin.checkGLErrors;
import static rs117.hd.renderer.zone.ZoneRenderer.TEXTURE_UNIT_TEXTURED_FACES;
import static rs117.hd.renderer.zone.ZoneRenderer.eboAlpha;
import static rs117.hd.utils.MathUtils.*;

@Slf4j
public class Zone implements Destructible {
	@Inject
	private Client client;

	// Zone vertex format
	// pos short vec3(x, y, z)
	// uvw short vec3(u, v, w)
	// normal short vec3(nx, ny, nz)
	// texturedFaceIdx int
	public static final int VERT_SIZE = 28;

	// alphaBiasHsl ivec3
	// materialData ivec3
	// terrainData ivec3
	public static final int TEXTURE_SIZE = 36;

	// Metadata format
	// worldViewIndex int int
	// sceneOffset int vec2(x, y)
	public static final int METADATA_SIZE = 12;

	public static final int LEVEL_WATER_SURFACE = 4;

	public int glVao;
	int bufLen;
	int dist;

	public int glVaoA;
	public int bufLenA;

	public int sizeO, sizeA, sizeF;
	@Nullable
	public GLBuffer vboO, vboA, vboM;
	public GLTextureBuffer tboF;

	public boolean initialized; // whether the zone vao and vbos are ready
	public boolean cull; // whether the zone is queued for deletion
	public boolean needsRoofUpdate; // whether the zone needs to have its roofs updated during scene swap
	public boolean rebuild; // whether the zone is queued for rebuild
	public boolean dirty; // whether the zone has temporary modifications
	public boolean hasWater; // whether the zone has any water tiles
	public boolean onlyWater; // whether the zone only contains water tiles
	public boolean inSceneFrustum; // whether the zone is visible to the scene camera
	public boolean inShadowFrustum; // whether the zone casts shadows into the visible scene
	public boolean isFirstLoadingAttempt = true;

	public HashSet<Integer> animatedDynamicObjectIds = new HashSet<>();

	final StaticAlphaSortingJob alphaSortingJob = new StaticAlphaSortingJob();
	ZoneUploadJob uploadJob;

	int[] levelOffsets = new int[5]; // buffer pos in ints for the end of the level

	int[][] rids;
	int[][] roofStart;
	int[][] roofEnd;

	final List<AlphaModel> alphaModels = new ArrayList<>(0);
	final ConcurrentLinkedQueue<AsyncCachedModel> pendingModelJobs = new ConcurrentLinkedQueue<>();

	public void initialize(GLBuffer o, GLBuffer a, GLTextureBuffer f) {
		assert glVao == 0;
		assert glVaoA == 0;
		if (o == null && a == null || f == null)
			return;

		vboM = new GLBuffer("ZoneMetadata", GL_ARRAY_BUFFER, GL_DYNAMIC_DRAW);
		vboM.initialize(METADATA_SIZE);

		if (o != null) {
			vboO = o;
			glVao = glGenVertexArrays();
			setupVao(glVao, o.id, vboM.id);
		}

		if (a != null) {
			vboA = a;
			glVaoA = glGenVertexArrays();
			setupVao(glVaoA, a.id, vboM.id);
		}

		tboF = f;
	}

	public static void freeZones(@Nullable Zone[][] zones) {
		if (zones == null)
			return;

		for (Zone[] column : zones)
			for (Zone zone : column)
				if (zone != null)
					zone.destroy();
	}

	@Override
	@SuppressWarnings("deprecation")
	protected void finalize() {
		if (glVao != 0 || glVaoA != 0)
			DestructibleHandler.queueLeakedDestruction(this);
	}

	@Override
	public void destroy() {
		if (vboO != null) {
			vboO.destroy();
			vboO = null;
		}

		if (vboA != null) {
			vboA.destroy();
			vboA = null;
		}

		if (vboM != null) {
			vboM.destroy();
			vboM = null;
		}

		if (tboF != null) {
			tboF.destroy();
			tboF = null;
		}

		if (glVao != 0) {
			glDeleteVertexArrays(glVao);
			glVao = 0;
		}

		if (glVaoA != 0) {
			glDeleteVertexArrays(glVaoA);
			glVaoA = 0;
		}

		if (uploadJob != null) {
			uploadJob.cancel();
			DestructibleHandler.destroy(uploadJob.zone);
			uploadJob = null;
		}

		sortedAlphaFacesUpload.release();

		sizeO = 0;
		sizeA = 0;
		sizeF = 0;
		bufLen = 0;
		bufLenA = 0;

		initialized = false;
		cull = false;
		hasWater = false;
		onlyWater = false;
		inSceneFrustum = false;
		inShadowFrustum = false;

		Arrays.fill(levelOffsets, 0);
		rids = null;
		roofStart = null;
		roofEnd = null;

		// don't add permanent alphamodels to the cache as permanent alphamodels are always allocated
		// to avoid having to synchronize the cache
		alphaModels.clear();
	}

	@Override
	public String toString() {
		return String.format(
			"Zone Initialized: %b, culled: %b hasUploadJob: %b opaqueSize: %d alphaSize: %d",
			initialized, cull, uploadJob != null, sizeO, sizeA
		);
	}

	public void unmap() {
		assert client.isClientThread();

		if (vboO != null)
			vboO.unmap();
		if (vboA != null)
			vboA.unmap();
		if (tboF != null)
			tboF.unmap();

		if (vboO != null) {
			this.bufLen = vboO.mapped().byteView().position() / VERT_SIZE;
		}

		if (vboA != null) {
			this.bufLenA = vboA.mapped().byteView().position() / VERT_SIZE;
		}
	}

	private void setupVao(int vao, int buffer, int metadata) {
		glBindVertexArray(vao);
		glBindBuffer(GL_ARRAY_BUFFER, buffer);

		// Position
		glEnableVertexAttribArray(0);
		glVertexAttribPointer(0, 3, GL_SHORT, false, VERT_SIZE, 0);

		// UVs
		glEnableVertexAttribArray(1);
		glVertexAttribPointer(1, 4, GL_HALF_FLOAT, false, VERT_SIZE, 8);

		// Normals
		glEnableVertexAttribArray(2);
		glVertexAttribPointer(2, 4, GL_SHORT, false, VERT_SIZE, 16);

		// TextureFaceIdx
		glEnableVertexAttribArray(3);
		glVertexAttribIPointer(3, 1, GL_INT, VERT_SIZE, 24);

		glBindBuffer(GL_ARRAY_BUFFER, metadata);

		// WorldView index (not ID)
		glEnableVertexAttribArray(6);
		glVertexAttribDivisor(6, 1);
		glVertexAttribIPointer(6, 1, GL_INT, METADATA_SIZE, 0);

		// Scene offset
		glEnableVertexAttribArray(7);
		glVertexAttribDivisor(7, 1);
		glVertexAttribIPointer(7, 2, GL_INT, METADATA_SIZE, 4);

		checkGLErrors();

		glBindVertexArray(0);
		glBindBuffer(GL_ARRAY_BUFFER, 0);
	}

	public void setMetadata(WorldViewContext viewContext, SceneContext sceneContext, int mx, int mz) {
		if (vboM == null)
			return;

		int baseX = (mx - (sceneContext.sceneOffset >> 3)) << 10;
		int baseZ = (mz - (sceneContext.sceneOffset >> 3)) << 10;

		try (MemoryStack stack = MemoryStack.stackPush()) {
			IntBuffer buf = stack.mallocInt(3)
				.put(viewContext.uboWorldViewStruct != null ? viewContext.uboWorldViewStruct.worldViewIdx + 1 : 0)
				.put(baseX)
				.put(baseZ);
			buf.flip();
			vboM.upload(buf);
		}
	}

	void updateRoofs(Map<Integer, Integer> updates) {
		for (int level = 0; level < 4; ++level) {
			for (int i = 0; i < rids[level].length; ++i) {
				rids[level][i] = updates.getOrDefault(rids[level][i], rids[level][i]);
			}
		}

		for (AlphaModel m : alphaModels) {
			m.rid = (short) (int) updates.getOrDefault((int) m.rid, (int) m.rid);
		}
	}

	private static final int NUM_DRAW_RANGES = 512;
	private static final int[] drawOff = new int[NUM_DRAW_RANGES];
	private static final int[] drawEnd = new int[NUM_DRAW_RANGES];

	private static final int[] glDrawOffset = new int[NUM_DRAW_RANGES];
	private static final int[] glDrawLength = new int[NUM_DRAW_RANGES];
	private static int drawIdx = 0;

	private void convertForDraw(int vertSize) {
		for (int i = 0; i < drawIdx; ++i) {
			assert drawEnd[i] >= drawOff[i];

			// convert from bytes to verts
			drawOff[i] /= vertSize >> 2;
			drawEnd[i] /= vertSize >> 2;

			drawEnd[i] -= drawOff[i]; // convert from end pos to length
		}

		copyTo(glDrawOffset, drawOff, 0, drawIdx);
		copyTo(glDrawLength, drawEnd, 0, drawIdx);
	}

	void renderOpaque(CommandBuffer cmd, WorldViewContext ctx, boolean roofShadows) {
		drawIdx = 0;

		int currentLevel = ctx.level;
		int maxLevel = ctx.maxLevel;
		var hiddenRoofIds = ctx.hideRoofIds;
		if (roofShadows) {
			maxLevel = 3;
			hiddenRoofIds = Collections.emptySet();
		}

		for (int level = ctx.minLevel; level <= maxLevel; ++level) {
			int[] rids = this.rids[level];
			int[] roofStart = this.roofStart[level];
			int[] roofEnd = this.roofEnd[level];

			if (rids.length == 0 || hiddenRoofIds.isEmpty() || level <= currentLevel) {
				// draw the whole level
				int start = level == 0 ? 0 : this.levelOffsets[level - 1];
				int end = this.levelOffsets[level];
				pushRange(start, end);
				continue;
			}

			for (int roofIdx = 0; roofIdx < rids.length; ++roofIdx) {
				int rid = rids[roofIdx];
				if (rid > 0 && !hiddenRoofIds.contains(rid)) {
					// draw the roof
					assert roofEnd[roofIdx] >= roofStart[roofIdx];
					if (roofEnd[roofIdx] > roofStart[roofIdx]) {
						pushRange(roofStart[roofIdx], roofEnd[roofIdx]);
					}
				}
			}

			// push from the end of the last roof to the end of the level
			int endpos = level == 0 ? 0 : this.levelOffsets[level - 1];
			for (int roofIdx = rids.length - 1; roofIdx >= 0; --roofIdx) {
				int rid = rids[roofIdx];
				if (rid > 0) {
					endpos = roofEnd[roofIdx];
					break;
				}
			}
			// draw the non roofs
			pushRange(endpos, this.levelOffsets[level]);
		}

		if (drawIdx == 0)
			return;

		lastDrawMode = STATIC_UNSORTED;
		lastVao = glVao;
		lastTboF = tboF.getTexId();
		flush(cmd);
	}

	void renderOpaqueLevel(CommandBuffer cmd, int level) {
		drawIdx = 0;

		pushRange(this.levelOffsets[level - 1], this.levelOffsets[level]);

		if (drawIdx == 0)
			return;

		lastDrawMode = STATIC_UNSORTED;
		lastVao = glVao;
		lastTboF = tboF.getTexId();
		flush(cmd);
	}

	private static void pushRange(int start, int end) {
		assert end >= start;

		if (drawIdx > 0 && drawEnd[drawIdx - 1] == start) {
			drawEnd[drawIdx - 1] = end;
		} else if (drawIdx >= NUM_DRAW_RANGES) {
			log.debug("draw ranges exhausted");
		} else {
			drawOff[drawIdx] = start;
			drawEnd[drawIdx] = end;
			drawIdx++;
		}
	}

	public static class AlphaModel {
		int id;
		ModelOverride modelOverride;
		int startpos, endpos;
		short x, y, z; // local position
		short rid;
		int vao;
		int tboF;
		byte level;
		byte lx, lz, ux, uz; // lower/upper zone coords
		byte zofx, zofz; // for temp alpha models, offset of source zone from target zone
		byte flags;

		// only set for static geometry as they require sorting
		int radius;
		int[] packedFaces;
		int[] sortedFaces;
		int sortedFacesLen;

		int dist;
		int asyncSortIdx = -1;

		static final int SKIP = 1; // temporary model is in a closer zone
		static final int TEMP = 2; // temporary model added to a closer zone
		static final int SORT_COMPLETED = 4;

		void setSorted() {
			flags |= SORT_COMPLETED;
		}

		boolean needsSorting() {
			return (flags & SORT_COMPLETED) == 0;
		}

		boolean isTemp() {
			return packedFaces == null || sortedFaces == null;
		}

		void setView(DynamicModelVAO.View view) {
			vao = view.vao;
			tboF = view.tboTexId;
			startpos = view.getStartOffset();
			endpos = view.getEndOffset();
		}
	}

	static final ConcurrentLinkedQueue<AlphaModel> modelCache = new ConcurrentLinkedQueue<>();

	void addAlphaModel(
		HdPlugin plugin,
		MaterialManager materialManager,
		int vao,
		int tboF,
		Model model,
		ModelOverride modelOverride,
		int startpos,
		int endpos,
		int x,
		int y,
		int z,
		int lx,
		int lz,
		int ux,
		int uz,
		int rid,
		int level,
		int id
	) {
		AlphaModel m = new AlphaModel();
		m.id = id;
		m.modelOverride = modelOverride;
		m.startpos = startpos;
		m.endpos = endpos;
		m.x = (short) x;
		m.y = (short) y;
		m.z = (short) z;
		m.vao = vao;
		m.tboF = tboF;
		m.rid = (short) rid;
		m.level = (byte) level;
		if (lx > -1) {
			m.lx = (byte) lx;
			m.lz = (byte) lz;
			m.ux = (byte) ux;
			m.uz = (byte) uz;
		} else {
			m.lx = m.lz = m.ux = m.uz = -1;
		}

		int faceCount = model.getFaceCount();
		short[] unlitColor = plugin.configUnlitFaceColors ? model.getUnlitFaceColors() : null;
		int[] color1 = model.getFaceColors1();
		int[] color3 = model.getFaceColors3();
		byte[] transparencies = model.getFaceTransparencies();
		short[] faceTextures = model.getFaceTextures();
		float[] vertexX = model.getVerticesX();
		float[] vertexY = model.getVerticesY();
		float[] vertexZ = model.getVerticesZ();
		int[] indices1 = model.getFaceIndices1();
		int[] indices2 = model.getFaceIndices2();
		int[] indices3 = model.getFaceIndices3();

		int minX = Integer.MAX_VALUE, minY = Integer.MAX_VALUE, minZ = Integer.MAX_VALUE;
		int maxX = Integer.MIN_VALUE, maxY = Integer.MIN_VALUE, maxZ = Integer.MIN_VALUE;

		for (int f = 0; f < faceCount; ++f) {
			if (color3[f] == -2)
				continue;

			boolean hasAlpha = modelOverride.mightHaveTransparency || transparencies != null && transparencies[f] != 0;
			if (!hasAlpha)
				continue;

			int fx = (int) (vertexX[indices1[f]] + vertexX[indices2[f]] + vertexX[indices3[f]]);
			int fy = (int) (vertexY[indices1[f]] + vertexY[indices2[f]] + vertexY[indices3[f]]);
			int fz = (int) (vertexZ[indices1[f]] + vertexZ[indices2[f]] + vertexZ[indices3[f]]);

			minX = Math.min(minX, fx);
			maxX = Math.max(maxX, fx);
			minY = Math.min(minY, fy);
			maxY = Math.max(maxY, fy);
			minZ = Math.min(minZ, fz);
			maxZ = Math.max(maxZ, fz);
		}

		int cx = (minX + maxX) / 6;
		int cy = (minY + maxY) / 6;
		int cz = (minZ + maxZ) / 6;

		int size = Math.max(
			Math.max(
				Math.max(maxX / 3 - cx, minX / -3 - cx),
				Math.max(maxY / 3 - cy, minY / -3 - cy) * 2
			),
			Math.max(maxZ / 3 - cz, minZ / -3 - cz)
		);

		int shift = 0;
		// 10 bits because we need a sign bit
		for (int v = size >> 10; v > 0; v >>= 1) {
			shift++;
		}

		int[] packedFaces = m.packedFaces = new int[(endpos - startpos) / ((3 * VERT_SIZE) >> 2)];
		int radius = 0;
		char bufferIdx = 0;
		for (int f = 0; f < faceCount; ++f) {
			if (color3[f] == -2)
				continue;

			// Hide fake shadows or lighting that is often baked into models by making the fake shadow transparent
			if (plugin.configHideFakeShadows && modelOverride.hideVanillaShadows && HDUtils.isBakedGroundShading(model, f))
				continue;

			int transparency = transparencies != null ? transparencies[f] & 0xFF : 0;
			int textureId = faceTextures != null ? faceTextures[f] : -1;

			ModelOverride faceOverride = modelOverride;

			Material material = modelOverride.baseMaterial;
			if (textureId != -1) {
				if (modelOverride.textureMaterial != Material.NONE) {
					material = modelOverride.textureMaterial;
				} else {
					material = materialManager.fromVanillaTexture(textureId);
					if (modelOverride.materialOverrides != null) {
						var override = modelOverride.materialOverrides.get(material);
						if (override != null) {
							faceOverride = override;
							material = override.textureMaterial;
						}
					}
				}
			} else if (modelOverride.colorOverrides != null) {
				final int ahsl = (0xFF - transparency) << 16 | (unlitColor != null ? unlitColor[f] & 0xFFFF : color1[f]);
				final var override = modelOverride.testColorOverrides(ahsl);
				if (override != null) {
					faceOverride = override;
					material = override.baseMaterial;
				}
			}

			if (faceOverride.hide)
				continue;

			boolean hasAlpha = material.hasTransparency || transparency != 0;
			if (!hasAlpha)
				continue;

			int fx = (((int) (vertexX[indices1[f]] + vertexX[indices2[f]] + vertexX[indices3[f]]) / 3) - cx) >> shift;
			int fy = (((int) (vertexY[indices1[f]] + vertexY[indices2[f]] + vertexY[indices3[f]]) / 3) - cy) >> shift;
			int fz = (((int) (vertexZ[indices1[f]] + vertexZ[indices2[f]] + vertexZ[indices3[f]]) / 3) - cz) >> shift;

			radius = Math.max(radius, fx * fx + fy * fy + fz * fz);

			packedFaces[bufferIdx] = ((fx & ((1 << 11) - 1)) << 21)
									 | ((fy & ((1 << 10) - 1)) << 11)
									 | (fz & ((1 << 11) - 1));
			bufferIdx++;
		}

		m.radius = 2 + (int) Math.sqrt(radius);
		m.sortedFaces = new int[bufferIdx * 3];

		assert packedFaces.length > 0;
		// Normally these will be equal, but transparency is used to hide faces in the TzHaar reskin
		assert bufferIdx <= packedFaces.length : String.format("%d > %d", (int) bufferIdx, packedFaces.length);

		alphaModels.add(m);
	}

	synchronized AlphaModel requestTempAlphaModel(ModelOverride modelOverride, int level, int x, int y, int z) {
		AlphaModel m = modelCache.poll();
		if (m == null)
			m = new AlphaModel();
		m.id = -1;
		m.modelOverride = modelOverride;
		m.x = (short) x;
		m.y = (short) y;
		m.z = (short) z;
		m.level = (byte) level;
		m.vao = m.tboF = m.rid = m.lx = m.lz = m.ux = m.uz = -1;
		m.flags = 0;
		m.zofx = m.zofz = 0;
		alphaModels.add(m);
		return m;
	}

	synchronized void postAlphaPass() {
		sortedAlphaFacesUpload.waitForCompletion();
		alphaSortingJob.waitForCompletion();

		for (int i = alphaModels.size() - 1; i >= 0; --i) {
			AlphaModel m = alphaModels.get(i);
			if (m.isTemp() || (m.flags & AlphaModel.TEMP) != 0) {
				alphaModels.remove(i);
				m.packedFaces = null;
				m.sortedFaces = null;
				modelCache.add(m);
			}
			m.asyncSortIdx = -1;
			m.flags &= ~(AlphaModel.SKIP | AlphaModel.SORT_COMPLETED);
		}
	}

	private static final int STATIC = 1;
	private static final int TEMP = 2;
	private static final int STATIC_UNSORTED = 3;

	private static int alphaFaceCount;
	private static int eboAlphaOffset;
	private static int lastDrawMode;
	private static int lastVao;
	private static int lastTboF;
	private static int lastzx, lastzz;

	private static final class AlphaSortPredicate implements ToIntFunction<AlphaModel> {
		int cx, cy, cz;
		int zx, zz;

		@Override
		public int applyAsInt(AlphaModel m) {
			final int mx = m.x + ((zx - m.zofx) << 10);
			final int mz = m.z + ((zz - m.zofz) << 10);
			final int my = m.y;
			return (mx - cx) * (mx - cx) + (my - cy) * (my - cy) + (mz - cz) * (mz - cz);
		}
	}

	private final AlphaSortPredicate alphaSortPred = new AlphaSortPredicate();
	private final Comparator<AlphaModel> alphaSortComparator = Comparator.comparingInt(alphaSortPred).reversed();

	private final EboAlphaWriterJob sortedAlphaFacesUpload = new EboAlphaWriterJob();

	synchronized void alphaSort(int zx, int zz, Camera camera) {
		alphaSortPred.cx = (int) camera.getPositionX();
		alphaSortPred.cy = (int) camera.getPositionY();
		alphaSortPred.cz = (int) camera.getPositionZ();
		alphaSortPred.zx = zx;
		alphaSortPred.zz = zz;
		alphaModels.sort(alphaSortComparator);
	}

	void alphaStaticModelSort(Camera camera) {
		alphaSortingJob.reset();
		for (AlphaModel m : alphaModels) {
			if ((m.flags & AlphaModel.SKIP) != 0 || m.isTemp())
				continue;

			m.dist = dist;
			alphaSortingJob.addAlphaModel(m);
		}
		alphaSortingJob.queue(camera);
	}

	void renderAlpha(
		CommandBuffer cmd,
		int zx,
		int zz,
		int level,
		WorldViewContext ctx,
		boolean isShadowPass,
		boolean includeRoof
	) {
		if (alphaModels.isEmpty())
			return;

		int minLevel = ctx.minLevel;
		int currentLevel = ctx.level;
		int maxLevel = ctx.maxLevel;
		var hiddenRoofIds = ctx.hideRoofIds;
		if (includeRoof) {
			maxLevel = 3;
			hiddenRoofIds = Collections.emptySet();
		}

		drawIdx = 0;

		cmd.DepthMask(false);

		if (!isShadowPass)
			sortedAlphaFacesUpload.waitForCompletion();

		int eboAlphaStart = eboAlphaOffset = ZoneRenderer.eboAlphaWriter.getWrittenInts();
		for (int i = 0; i < alphaModels.size(); i++) {
			final AlphaModel m = alphaModels.get(i);
			if ((m.flags & AlphaModel.SKIP) != 0 || m.level != level || m.vao == -1)
				continue;

			if (level < minLevel || level > maxLevel ||
				level > currentLevel && !hiddenRoofIds.isEmpty() && hiddenRoofIds.contains((int) m.rid))
				continue;

			int drawMode = STATIC;
			if (m.isTemp()) {
				// these are already sorted and so just requires a glMultiDrawArrays() from the active vao
				drawMode = TEMP;
			} else if (isShadowPass || m.asyncSortIdx < 0) {
				drawMode = STATIC_UNSORTED;
			}

			if (lastDrawMode != drawMode ||
				lastVao != m.vao ||
				lastTboF != m.tboF ||
				lastzx != (zx - m.zofx) ||
				lastzz != (zz - m.zofz)
			) {
				flush(cmd);
				lastDrawMode = drawMode;
				lastVao = m.vao;
				lastTboF = m.tboF;
				lastzx = zx - m.zofx;
				lastzz = zz - m.zofz;
			}

			if (drawMode != STATIC) {
				pushRange(m.startpos, m.endpos);
				continue;
			}

			// Check if we the faces have already been sorted, if not then the client will steal the work,
			// if the model is already being processed then we'll have to wait for the result to finish
			if (m.needsSorting() && !alphaSortingJob.forceProcessModelClient(m)) {
				while (m.needsSorting() && !alphaSortingJob.isDone())
					alphaSortingJob.waitForCompletion(10);
			}

			if (m.sortedFaces == null || m.sortedFacesLen <= 0)
				continue;

			sortedAlphaFacesUpload.alphaModels.add(m);

			eboAlphaOffset += m.sortedFacesLen;
			alphaFaceCount += m.sortedFacesLen / 3;
			lastDrawMode = STATIC;
		}

		if (eboAlphaOffset > eboAlphaStart && !sortedAlphaFacesUpload.alphaModels.isEmpty()) {
			sortedAlphaFacesUpload.eboAlphaView = ZoneRenderer.eboAlphaWriter.reserve(eboAlphaOffset - eboAlphaStart);
			sortedAlphaFacesUpload.queue();
		}

		flush(cmd);

		cmd.DepthMask(true);
	}

	private void flush(CommandBuffer cmd) {
		if (lastDrawMode == STATIC) {
			if (alphaFaceCount > 0 && lastVao != 0) {
				int vertexCount = alphaFaceCount * 3;
				long byteOffset = 4L * (eboAlphaOffset - vertexCount);
				cmd.BindVertexArray(lastVao, eboAlpha);
				cmd.BindTextureUnit(GL_TEXTURE_BUFFER, lastTboF, TEXTURE_UNIT_TEXTURED_FACES);
				// The EBO & IDO is bound by in ZoneRenderer
				if (GL_CAPS.OpenGL40 && SUPPORTS_INDIRECT_DRAW) {
					cmd.DrawElementsIndirect(GL_TRIANGLES, vertexCount, (int) (byteOffset / 4L), ZoneRenderer.indirectDrawCmdsStaging);
				} else {
					cmd.DrawElements(GL_TRIANGLES, vertexCount, byteOffset);
				}
			}
			alphaFaceCount = 0;
		} else if (drawIdx != 0) {
			convertForDraw(lastDrawMode == STATIC_UNSORTED ? VERT_SIZE : DynamicModelVAO.VERT_SIZE);
			cmd.BindVertexArray(lastVao);
			cmd.BindTextureUnit(GL_TEXTURE_BUFFER, lastTboF, TEXTURE_UNIT_TEXTURED_FACES);
			if (drawIdx == 1) {
				if (GL_CAPS.OpenGL40 && SUPPORTS_INDIRECT_DRAW) {
					cmd.DrawArraysIndirect(GL_TRIANGLES, drawOff[0], drawEnd[0], ZoneRenderer.indirectDrawCmdsStaging);
				} else {
					cmd.DrawArrays(GL_TRIANGLES, drawOff[0], drawEnd[0]);
				}
			} else {
				if (GL_CAPS.OpenGL43 && SUPPORTS_INDIRECT_DRAW) {
					cmd.MultiDrawArraysIndirect(GL_TRIANGLES, glDrawOffset, glDrawLength, drawIdx, ZoneRenderer.indirectDrawCmdsStaging);
				} else {
					cmd.MultiDrawArrays(GL_TRIANGLES, glDrawOffset, glDrawLength, drawIdx);
				}
			}
			drawIdx = 0;
		}
	}

	synchronized void multizoneLocs(SceneContext ctx, int zx, int zz, Camera camera, Zone[][] zones) {
		int offset = ctx.sceneOffset >> 3;
		int cx = (int) camera.getPositionX();
		int cz = (int) camera.getPositionZ();
		for (int i = 0; i < alphaModels.size(); i++) {
			final AlphaModel m = alphaModels.get(i);
			if (m.lx == -1)
				continue;

			// calculate which zone this model should be drawn from
			// TODO fix for boats
			int max = Integer.MAX_VALUE;
			int closestZoneX = -50, closestZoneZ = -50;
			for (int x = m.lx >> 3; x <= m.ux >> 3; ++x) {
				for (int z = m.lz >> 3; z <= m.uz >> 3; ++z) {
					int centerX = (zx - m.zofx + x) * 8 + 4 << 7;
					int centerZ = (zz - m.zofz + z) * 8 + 4 << 7;
					int distance = (centerX - cx) * (centerX - cx) +
								   (centerZ - cz) * (centerZ - cz);
					if (distance < max) {
						int zx2 = (centerX >> 10) + offset;
						int zz2 = (centerZ >> 10) + offset;
						if (zx2 >= 0 && zx2 < zones.length && zz2 >= 0 && zz2 < zones[0].length) {
							if (zones[zx2][zz2].inSceneFrustum && zones[zx2][zz2].initialized) {
								max = distance;
								closestZoneX = centerX >> 10;
								closestZoneZ = centerZ >> 10;
							}
						}
					}
				}
			}
			if (closestZoneX != -50 && (closestZoneX != zx || closestZoneZ != zz)) {
				assert closestZoneX + offset >= 0 : closestZoneX;
				assert closestZoneX + offset < zones.length : closestZoneX;
				assert closestZoneZ + offset >= 0 : closestZoneZ;
				assert closestZoneZ + offset < zones[0].length : closestZoneZ;

				Zone z = zones[closestZoneX + offset][closestZoneZ + offset];
				assert z != null;
				assert z != this;

				AlphaModel m2 = modelCache.poll();
				if (m2 == null)
					m2 = new AlphaModel();
				m2.id = m.id;
				m2.modelOverride = m.modelOverride;
				m2.startpos = m.startpos;
				m2.endpos = m.endpos;
				m2.x = m.x;
				m2.y = m.y;
				m2.z = m.z;
				m2.vao = m.vao;
				m2.tboF = m.tboF;
				m2.rid = m.rid;
				m2.level = m.level;
				m2.lx = m.lx;
				m2.lz = m.lz;
				m2.ux = m.ux;
				m2.uz = m.uz;
				m2.zofx = (byte) (closestZoneX - zx);
				m2.zofz = (byte) (closestZoneZ - zz);

				m2.packedFaces = m.packedFaces;
				m2.radius = m.radius;
				m2.asyncSortIdx = m.asyncSortIdx;
				m2.sortedFaces = m.sortedFaces;
				m2.sortedFacesLen = m.sortedFacesLen;

				m2.flags = AlphaModel.TEMP;
				m.flags |= AlphaModel.SKIP;

				z.alphaModels.add(m2);
			}
		}
	}
}

